["CCS Player Spec Change"] = {
["iconSource"] = -1,
["wagoID"] = "bRl2gJIgz",
["parent"] = "Chonky Char WA (QUI MOD)",
["adjustedMax"] = "",
["customText"] = "\n\n",
["yOffset"] = 0,
["anchorPoint"] = "BOTTOMLEFT",
["cooldownSwipe"] = true,
["customTextUpdate"] = "event",
["cooldownEdge"] = false,
["actions"] = {
["start"] = {
["do_glow"] = false,
["custom"] = "\n\n",
["glow_action"] = "show",
["do_custom"] = false,
["glow_frame"] = "WeakAuras:Talents\\Items",
},
["finish"] = {
["custom"] = "aura_env.region:SetScript(\"OnEnter\", nil)\naura_env.region:SetScript(\"OnLeave\", nil)\naura_env.region:EnableMouse(false)",
["do_custom"] = true,
},
["init"] = {
["custom"] = "if not aura_env.fix then\n    aura_env.fix = true\n    C_Timer.After(1, function() WeakAuras.ScanEvents(\"PLAYER_SPECIALIZATION_CHANGED\") end)\nend\n\naura_env.tips = {}\nlocal aura_env = aura_env\nlocal c = aura_env.config\nlocal region = WeakAuras.GetRegion(aura_env.id)\nlocal SPECIALIZATION = SPECIALIZATION\nlocal _G = _G\nlocal LSM = LibStub(\"LibSharedMedia-3.0\");\nlocal charsheet = WeakAuras.GetData(\"CCS Character Sheet\")\nlocal nukeit = charsheet.config.nukeit\n\naura_env.sortAndOffset = function()\n    -- initialize button spacing.\n    local spacing = 3\n    local Width = region:GetWidth()\n    local Height = region:GetHeight()\n    local xDistance = Width + spacing        \n    local specIndex = GetSpecialization();\n    \n    local textoptions = charsheet.config.textoutline\n    \n    if textoptions == 1 then textoptions = \"\"\n    elseif textoptions == 2 then textoptions = \"OUTLINE\"\n    elseif textoptions == 3 then textoptions = \"THICKOUTLINE\"\n    end\n    \n    \n    if c.showspec and not nukeit then \n        \n        for count=1, 4, 1 do -- count up to 4 (since druids have 4 specs)\n            local id, name, _, icon = GetSpecializationInfo(count); -- spec info for the loop\n            local link = nil -- this is placeholder for other weakauras\n            local spellid = nil -- this is placeholder for other weakauras\n            local description = \"\" -- this is placeholder for other weakauras\n            local xOffset = 5 + (xDistance * (count-1)) \n            local yOffset = 5\n            local btn = _G[aura_env.id..\"Btn\"..count]\n            \n            if ( id and id ~= 0) then\n                -- begin clickable button frame\n                \n                if btn == nil then btn = CreateFrame(\"Button\", aura_env.id..\"Btn\"..count, region, \"UIPanelButtonTemplate\") end\n                btn:SetSize(Width, Height)\n                btn:SetPoint(\"BOTTOMLEFT\", PaperDollItemsFrame, \"BOTTOMLEFT\", xOffset, yOffset)\n                btn:SetNormalTexture(icon)\n                btn:SetFrameStrata(\"HIGH\")\n                \n                local btnfont1 = _G[btn:GetName()..\"fs1\"]\n                \n                if count == 1 and btnfont1 == nil and c.showspectitle then \n                    \n                    btnfont1 = btn:CreateFontString(btn:GetName()..\"fs1\")\n                    btnfont1:SetPoint(\"BOTTOMLEFT\", btn, \"TOPLEFT\",0 ,3)\n                    btnfont1:SetFont(LSM:Fetch(\"font\", charsheet.subRegions[2].text_font), (c.fontsize_specs or 10), textoptions)\n                    btnfont1:SetText(SPECIALIZATION)                    \n                end\n                \n                local btntex = _G[btn:GetName()..\"tex\"]\n                if btntex == nil then btntex = btn:CreateTexture(btn:GetName()..\"tex\", \"OVERLAY\") end\n                \n                btntex:SetAllPoints(btn)\n                region:Show()\n                btn:Show()\n                btntex:Show()\n                \n                if count == specIndex then btntex:SetTexture(\"Interface\\\\ContainerFrame\\\\UI-Icon-QuestBorder.blp\")\n                else btntex:SetColorTexture(0,0,0,.65)\n                end\n                \n                btn:SetScript(\"OnEnter\", function() GameTooltip:SetOwner(UIParent, \"ANCHOR_CURSOR\")\n                        if link then\n                            GameTooltip:SetHyperlink(link)\n                        else\n                            GameTooltip:AddDoubleLine(name, spellid, 1, 1, 1, 1, 1, 1) \n                            GameTooltip:AddLine(description, nil, nil, nil, true)   \n                        end\n                        GameTooltip:Show()\n                end)\n                btn:SetScript(\"OnLeave\", function() GameTooltip:Hide() end)\n                \n                \n                btn:SetScript(\"OnClick\", function() -- Add specific functionality when clicking the button\n                        if count ~= specIndex then \n                            if SetSpecialization == nil then\n                                C_SpecializationInfo.SetSpecialization(count) \n                            else\n                                SetSpecialization(count) \n                            end\n                        end \n                        PlaySound(SOUNDKIT.GS_LOGIN_CHANGE_REALM_OK); -- just puts a sound in when clicking on the button for more feedback\n                end)\n                -- end clickable button frame\n                \n            end\n            \n            \n            \n        end\n        \n    end\nend   \n\nif not aura_env.WA_SPEC_SETUP then\n    aura_env.WA_SPEC_SETUP = true\nend\n\n\n\n\n\n",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
