["custom"] = "--MAIN TRIGGER\nfunction(states, event, ...)\n    if event == \"OPTIONS\" then\n        states[\"\"] = {\n            name = \"\",\n            icon = \"Interface\\\\addons\\\\WeakAuras\\\\Media\\\\Textures\\\\icon.blp\",\n            duration = 8,\n            expirationTime = GetTime() + 8,\n            progressType = \"timed\",\n            autoHide = true,\n            changed = true,\n            show = true,\n        }\n        return true\n    end\n    if event == \"WA_SPEC_SETUP\" and ... then\n        local aura_env = aura_env\n        C_Timer.After(0.1, function() aura_env.sortAndOffset() end)\n        return true\n        \n    end\nend",
