["custom"] = "",
["do_custom"] = false,
},
["init"] = {
["custom"] = "--[ DMUI Constants ]--\n\nlocal ascentSpellId = 372610\nlocal thrillBuffId = 377234\nlocal slowSkyridingRatio = 705 / 830\nlocal ascentDuration = 3.5\nlocal tickRate = 1 / 20\nlocal fastFlyingZones = {\n  [2444] = true,   -- Dragon Isles\n  [2454] = true,   -- Zaralek Cavern\n  [2548] = true,   -- Emerald Dream\n\n  [2516] = true,   -- Nokhud Offensive\n\n  [2522] = true,   -- Vault of the Incarnates\n  [2569] = true,   -- Aberrus, the Shadowed Crucible\n}\n\n--[ Options ]--\n\nlocal speedShow = aura_env.config.speedShow\nlocal hideDefaultVigorUI = aura_env.config.hideDefaultVigorUI\n\nlocal speedTextFormat, speedTextFactor = \"\", 1\nif aura_env.config.speedUnits == 1 then\n  speedTextFormat = \"%.1fyd/s\"\nelse\n  speedTextFormat = \"%.0f%%\"\n  speedTextFactor = 100 / 7\nend\n\n--[ Variables ]--\n\nlocal active = false\nlocal updateHandle = nil\nlocal ascentStart = 0\nlocal isSlowSkyriding = true\n\n--[ Localized Functions ]--\n\nlocal ScanEvents = WeakAuras.ScanEvents\nlocal GetTime = GetTime\n\n--[ Trigger 1 ]--\n\n-- Events:\n--   UNIT_SPELLCAST_SUCCEEDED:player\n--   LIROO_DRAGONRIDING_TICK\n\nlocal function setActive(allstates, state)\n  active = state\n\n  if active then\n    if hideDefaultVigorUI and UIWidgetPowerBarContainerFrame:IsVisible() then\n      aura_env.reshow = true\n      UIWidgetPowerBarContainerFrame:Hide()\n    end\n\n    if not updateHandle then\n      updateHandle = C_Timer.NewTicker(tickRate, function()\n        if active then\n          ScanEvents(\"LIROO_DRAGONRIDING_TICK\", true)\n        end\n      end)\n    end\n\n    if not allstates[\"\"] then\n      allstates[\"\"] = {\n        show = true,\n        changed = true,\n        progressType = \"static\",\n        value = 0,\n        accel = 0,\n        total = 100,\n        boosting = false,\n        thrill = false,\n        speedtext = \"\",\n        angle = \"\",\n      }\n      return true\n    end\n  else\n    if updateHandle then\n      updateHandle:Cancel()\n      updateHandle = nil\n    end\n\n    if allstates[\"\"] then\n      allstates[\"\"].show = false\n      allstates[\"\"].changed = true\n      return true\n    end\n  end\nend\n\naura_env.trigger1 = function(allstates, event, _, newAngle, spellId)\n  if event == \"OPTIONS\" then\n    return setActive(allstates, false)\n  end\n\n  if event == \"STATUS\" then\n    isSlowSkyriding = not fastFlyingZones[select(8, GetInstanceInfo())]\n    return setActive(allstates, true)\n  end\n\n  -- Detect ascent boost\n  if event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n    if spellId == ascentSpellId then\n      ascentStart = GetTime()\n    end\n    return false\n  end\n\n  if event ~= \"LIROO_DRAGONRIDING_TICK\" then\n    return false\n  end\n\n  local time = GetTime()\n\n  if not allstates or not allstates[\"\"] then return false end\n\n  -- Get flying speed\n  local isGliding, _, forwardSpeed = C_PlayerInfo.GetGlidingInfo()\n\n  local thrill = C_UnitAuras.GetPlayerAuraBySpellID(thrillBuffId)\n  local boosting = thrill and time < ascentStart + ascentDuration\n\n  local adjustedSpeed = forwardSpeed\n  if isSlowSkyriding then\n    adjustedSpeed = adjustedSpeed / slowSkyridingRatio\n  end\n\n  -- Update display variables\n  local s = allstates[\"\"]\n  s.changed = true\n  s.value = adjustedSpeed\n  s.boosting = boosting\n  s.thrill = not not thrill\n\n  if speedShow then\n    s.speedtext = forwardSpeed < 1 and \"\" or string.format(speedTextFormat, forwardSpeed * speedTextFactor)\n  end\n\n  return true\nend\n\naura_env.cancelCallback = function()\n  if updateHandle then\n    updateHandle:Cancel()\n    updateHandle = nil\n  end\nend\n",
["do_custom"] = true,
},
["finish"] = {
["custom"] = "if aura_env.reshow then\n  UIWidgetPowerBarContainerFrame:Show()\n  aura_env.reshow = false\nend\naura_env.cancelCallback()",
["do_custom"] = true,
},
},
