["trigger"] = {
["spellId"] = {
"198103",
},
["duration"] = "60",
["subeventPrefix"] = "SPELL",
["use_unit"] = true,
["dynamicDuration"] = false,
["names"] = {
},
["debuffType"] = "HELPFUL",
["custom_hide"] = "timed",
["spellIds"] = {
},
["type"] = "custom",
["events"] = "PLAYER_ENTERING_WORLD PLAYER_TOTEM_UPDATE PLAYER_TARGET_CHANGED CLEU:SWING_DAMAGE:SWING_HEAL:RANGE_DAMAGE:RANGE_HEAL:ENVIRONMENTAL_DAMAGE:ENVIRONMENTAL_HEAL:SPELL_DAMAGE:SPELL_HEAL:SPELL_PERIODIC_DAMAGE:SPELL_PERIODIC_HEAL:SPELL_SUMMON ",
["custom_type"] = "stateupdate",
["unevent"] = "timed",
["subeventSuffix"] = "_CAST_SUCCESS",
["event"] = "Combat Log",
["use_absorbMode"] = true,
["customDuration"] = "\n\n",
["use_spellId"] = true,
["custom"] = "function(states, event, ...)\n    if event == \"OPTIONS\" then\n        local name, _, icon = GetSpellInfo(198103)\n        local value = UnitHealthMax(\"player\") * 1.5\n        local percent = (value*0.75)/value*100\n        states[\"\"] = {\n            name = name,\n            icon = icon,\n            data = {\n                value = value*0.75,\n                total = value,\n                percent = percent,\n                percentDisplay = string.format(\"%.1f%%\"),\n            },\n            duration = 60,\n            expirationTime = GetTime() + 60,\n            progressType = \"timed\",\n            autoHide = false,\n            changed = true,\n            show = true,\n        }\n        return true\n    end\n    if event == \"PLAYER_ENTERING_WORLD\" and states[\"\"] then\n        states[\"\"].show = false\n        states[\"\"].changed = true\n        wipe(aura_env.data)\n        aura_env.region.destGUID = nil\n        return true\n    elseif event == \"PLAYER_TOTEM_UPDATE\" then\n        local arg = ...\n        if arg then --actual event\n            local haveTotem, name, startTime, duration, icon = GetTotemInfo(arg)\n            if haveTotem and icon == 136024 then\n                states[\"\"] = {\n                    name = name,\n                    icon = icon,\n                    arg = arg,\n                    destGUID = aura_env.region.destGUID or \"\",\n                    duration = duration,\n                    expirationTime = startTime + duration,\n                    progressType = \"timed\",\n                    autoHide = true,\n                    changed = true,\n                    show = true,\n                }\n                if aura_env.data then\n                    states[\"\"].data = CopyTable(aura_env.data)\n                    wipe(aura_env.data)\n                end\n                return true\n            elseif states[\"\"] and states[\"\"].arg == arg then\n                states[\"\"].show = false\n                states[\"\"].changed = true\n                wipe(aura_env.data)\n                aura_env.region.destGUID = nil\n                return true\n            end\n        else --options closed\n            for i=1, 5 do\n                local haveTotem, name, startTime, duration, icon = GetTotemInfo(i)\n                if haveTotem and icon == 136024 then\n                    states[\"\"] = {\n                        name = name,\n                        icon = icon,\n                        arg = i,\n                        destGUID = aura_env.region.destGUID or \"\",\n                        duration = duration,\n                        expirationTime = startTime + duration,\n                        progressType = \"timed\",\n                        autoHide = true,\n                        changed = true,\n                        show = true,\n                    }\n                    return true\n                end\n            end\n        end\n    elseif event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local _, message, _, srcGUID, srcName, _, _, destGUID, destName, _, _, spellid = ...\n        \n        if message == \"SPELL_SUMMON\"\n        and srcGUID == WeakAuras.myGUID\n        and spellid == 188616\n        then\n            for _, v in pairs(states) do\n                v.show = false\n                v.changed = true\n            end\n            local value = UnitHealthMax(\"player\") * 1.5\n            local percent = value/value*100\n            aura_env.data = {\n                value = value,\n                total = value,\n                percent = percent,\n                percentDisplay = string.format(\"%.1f%%\", percent),\n            }\n            aura_env.region.destGUID = destGUID\n            return true\n        elseif states[\"\"] then\n            local state = states[\"\"]\n            local subEvents = aura_env.subEvents\n            if state.destGUID == destGUID and state.data and state.data.value and subEvents[message] then\n                state.data.value = subEvents[message](state.data.value, state.data.total, ...)\n                local percent = state.data.value/state.data.total*100\n                state.data.percent = percent\n                state.data.percentDisplay = string.format(\"%.1f%%\", percent)\n                state.changed = true\n                return true\n            end\n        end\n    elseif event == \"PLAYER_TARGET_CHANGED\" and UnitExists(\"target\") and states[\"\"] then\n        local unit = \"target\"\n        local state = states[\"\"]\n        \n        local tGUID, ttGUID = UnitGUID(unit), nil\n        local exists = state.destGUID == tGUID\n        \n        if not exists then\n            unit = \"targettarget\"\n            ttGUID = UnitGUID(unit)\n            exists = state.destGUID == ttGUID\n        end\n        if exists then\n            if state.data and state.data.value then\n                state.data.value, state.data.total = UnitHealth(unit), UnitHealthMax(unit)\n                local percent = state.data.value/state.data.total*100\n                state.data.percent = percent\n                state.data.percentDisplay = string.format(\"%.1f%%\", percent)\n                state.changed = true\n                return true\n            else \n                local u = state.destGUID == tGUID and \"target\" or \"targettarget\"\n                local value, total = UnitHealth(u), UnitHealthMax(u) or 1\n                local percent = value/total*100\n                state.data = {\n                    value = value,\n                    total = total,\n                    percent = percent,\n                    percentDisplay = string.format(\"%.1f%%\", percent),\n                }\n                state.changed = true\n                return true\n            end\n        end\n    end\nend",
