["subeventSuffix"] = "_CAST_START",
["subeventPrefix"] = "SPELL",
["event"] = "Health",
["unit"] = "player",
["custom"] = "-- Put this in Trigger 1 -> Custom Trigger\nfunction()\n    local theTime = GetTime()\n    -- Throttle check (update approx twice per second)\n    if not aura_env.last or aura_env.last < theTime - 0.5 then\n        aura_env.last = theTime\n        -- Always get 24-hour format hour (00-23)\n        aura_env.hour = date(\"%H\")\n        -- Always get minute (00-59)\n        aura_env.minute = date(\"%M\")\n    end\n    -- Trigger always returns true so Name Info can be generated\n    return true\nend",
["customName"] = "-- Put this in Trigger 1 -> Name Info -> Custom Function\nfunction()\n    -- Check if hour and minute have been calculated by the trigger yet\n    if aura_env.hour and aura_env.minute then\n        -- Format directly as HH:MM (white text implicit unless Display sets color)\n        return string.format(\"%s:%s\", aura_env.hour, aura_env.minute)\n    else\n        -- Default value if data isn't ready\n        return \"00:00\"\n    end\nend",
