["init"] = {
["custom"] = "local e=aura_env;\ne.Tick=GetTime()\ne.col='|c'..select(4,GetClassColor(UnitClassBase('player')));\n\ne.C = function(t)\n    if t>400 then \n        t='|cff00ff00'..t..'|r';\n    elseif t>120 then\n        t='|cffffff00'..t..'|r';\n    else\n        t='|cff00ff00'..t..'|r';\n    end    \n    return t\nend\n\n\n",
["do_custom"] = true,
},
},
