["fixedWidth"] = 120,
["backgroundOffset"] = 2,
["outline"] = "OUTLINE",
["wagoID"] = "BeTqCilHR",
["parent"] = "QUI Datatext Panel",
["customText"] = "function()\n    local e = aura_env\n    local tick = GetTime()\n    if tick - e.Tick < 0.4 and tick > e.Tick then\n        return e.re\n    else\n        e.Tick = tick\n    end\n    \n    local latencyHome, latencyWorld = select(3, GetNetStats())\n    local t = e.C(latencyWorld)\n    \n    if e.config.h then\n        t = t .. '[' .. e.C(latencyHome) .. ']'\n    end\n    \n    e.re = t\n    return e.re\nend",
