["custom_hide"] = "timed",
["subeventPrefix"] = "SPELL",
["event"] = "Combat Log",
["events"] = "CLEU:SPELL_CAST_SUCCESS:UNIT_DIED",
["custom"] = "function(allstates, event, timestamp, subEvent,  ...)\n    local _, sourceGUID, sourceName, _, _, destGUID, destName, _, _, spellID, spellName = ...\n    if subEvent == \"SPELL_CAST_SUCCESS\" then\n        -- spell cast\n        if spellID == 98008 then\n            local sourceUnit\n            for unit in WA_IterateGroupMembers() do\n                if UnitGUID(unit) == sourceGUID then\n                    sourceUnit = unit\n                end\n            end\n            -- group check\n            if not sourceUnit then return end\n            allstates[sourceGUID] = {\n                show = true,\n                changed = true,\n                unitCaster = sourceUnit,\n                progressType = \"timed\",\n                duration = 6,\n                expirationTime = GetTime() + 6,\n                autoHide = true,\n            }\n            return true\n        end\n    elseif subEvent == \"UNIT_DIED\" then \n        if not destGUID or not allstates[destGUID] then return end\n        allstates[destGUID].show = false\n        allstates[destGUID].changed = true\n        return true\n    end\n    \nend",
