["init"] = {
["custom"] = "local aura_env = aura_env\nlocal c = aura_env.config\nlocal region = WeakAuras.GetRegion(aura_env.id)\nlocal _G = _G\nlocal _, _, _, tocversion = GetBuildInfo()\nlocal LSM = LibStub(\"LibSharedMedia-3.0\");\nlocal charsheet = WeakAuras.GetData(\"CCS Character Sheet\")\nlocal nukeit = charsheet.config.nukeit\nlocal WA_Font = LSM:Fetch(\"font\", charsheet.subRegions[2].text_font)\n\naura_env.RAID_DIFFICULTY_COLORS ={\n    [1] = { 0.12, 1.00, 0.00, 'ff1eff00' }, \n    [2] = { 0.00, 0.44, 0.87, 'ff0070dd' },\n    [3] = { 0.64, 0.21, 0.93, 'ffa335ee' }\n}\n\naura_env.RAID_DIFFICULTY_NAMES = {\n    [1] = PLAYER_DIFFICULTY1, -- Normal\n    [2] = PLAYER_DIFFICULTY2, -- Heroic\n    [3] = PLAYER_DIFFICULTY6  -- Mythic\n}\n\naura_env.SRI = { \n    \n    -- Liberation of Undermine C_Map.GetMapInfo(2406).name\n    [1] = { name = select(1, EJ_GetEncounterInfo(2639)), icon = select(5, EJ_GetCreatureInfo(1, 2639)), normal=41300, heroic=41301, mythic=41302}, -- Vexie and the Geargrinders\n    [2] = { name = select(1, EJ_GetEncounterInfo(2640)), icon = select(5, EJ_GetCreatureInfo(1, 2640)), normal=41304, heroic=41305, mythic=41306}, -- Cauldrons of Carnage\n    [3] = { name = select(1, EJ_GetEncounterInfo(2641)), icon = select(5, EJ_GetCreatureInfo(1, 2641)), normal=41308, heroic=41309, mythic=41310}, -- Rik Reverb\n    [4] = { name = select(1, EJ_GetEncounterInfo(2642)), icon = select(5, EJ_GetCreatureInfo(1, 2642)), normal=41312, heroic=41313, mythic=41314}, -- Stix Bunkjunker\n    [5] = { name = select(1, EJ_GetEncounterInfo(2653)), icon = select(5, EJ_GetCreatureInfo(1, 2653)), normal=41316, heroic=41317, mythic=41318}, -- Sprocketmonger Lockenstock\n    [6] = { name = select(1, EJ_GetEncounterInfo(2644)), icon = select(5, EJ_GetCreatureInfo(1, 2644)), normal=41320, heroic=41321, mythic=41322}, -- The One-Armed Bandit\n    [7] = { name = select(1, EJ_GetEncounterInfo(2645)), icon = select(5, EJ_GetCreatureInfo(1, 2645)), normal=41324, heroic=41325, mythic=41326}, -- Mug'Zee, Heads of Security\n    [8] = { name = select(1, EJ_GetEncounterInfo(2646)), icon = select(5, EJ_GetCreatureInfo(1, 2646)), normal=41328, heroic=41329, mythic=41330}, -- Chrome King Gallywix\n    \n    -- Manaforge Omega C_Map.GetMapInfo(2460).name\n    [11] = { name = select(1, EJ_GetEncounterInfo(2684)), icon = select(5, EJ_GetCreatureInfo(1, 2684)), normal=41634, heroic=41635, mythic=41636}, -- Plexus Sentinel\n    [12] = { name = select(1, EJ_GetEncounterInfo(2686)), icon = select(5, EJ_GetCreatureInfo(1, 2686)), normal=41638, heroic=41639, mythic=41640}, -- Loom'ithar \n    [13] = { name = select(1, EJ_GetEncounterInfo(2685)), icon = select(5, EJ_GetCreatureInfo(1, 2685)), normal=41642, heroic=41643, mythic=41644}, -- Soulbinder Naazindhri\n    [14] = { name = select(1, EJ_GetEncounterInfo(2687)), icon = select(5, EJ_GetCreatureInfo(1, 2687)), normal=41646, heroic=41647, mythic=41648}, -- Forgeweaver Araz\n    [15] = { name = select(1, EJ_GetEncounterInfo(2688)), icon = select(5, EJ_GetCreatureInfo(1, 2688)), normal=41650, heroic=41651, mythic=41652}, -- The Soul Hunters\n    [16] = { name = select(1, EJ_GetEncounterInfo(2747)), icon = select(5, EJ_GetCreatureInfo(1, 2747)), normal=41654, heroic=41655, mythic=41656}, -- Fractillus\n    [17] = { name = select(1, EJ_GetEncounterInfo(2690)), icon = select(5, EJ_GetCreatureInfo(1, 2690)), normal=41658, heroic=41659, mythic=41660}, -- Nexus-King Salhadaar\n    [18] = { name = select(1, EJ_GetEncounterInfo(2691)), icon = select(5, EJ_GetCreatureInfo(1, 2691)), normal=41662, heroic=41663, mythic=41664}, -- Dimensiue, the All-Devouring\n    \n}\n\naura_env.bosscount = function(statID)\n    local bc = GetStatistic(statID)\n    if (bc == nil or bc == \"--\") then bc = 0 else bc = tonumber(bc) end\n    return bc\nend\n\naura_env.getprogression = function()\n    local normal,heroic,mythic=0,0,0;\n    \n    for x=1,8 do \n        local y\n        if tocversion < 110200 then y = x\n        elseif tocversion >= 110200 then y = x+10\n        end\n        \n        if aura_env.bosscount(aura_env.SRI[y].normal) > 0 then normal = normal + 1 end\n        if aura_env.bosscount(aura_env.SRI[y].heroic) > 0 then heroic = heroic + 1 end\n        if aura_env.bosscount(aura_env.SRI[y].mythic) > 0 then mythic = mythic + 1 end\n    end\n    \n    return normal, heroic, mythic\nend\n\naura_env.getraidstring = function()\n    local returnvalue\n    local M_prog_string=\"\" \n    local H_prog_string=\"\"\n    local N_prog_string=\"\"\n    local name_string=\"\"\n    if tocversion < 110200 then name_string = \"LOU\"\n    elseif tocversion >= 110200 then name_string = \"MO\"\n    end\n    \n    if c.showraidprogress ~= true or nukeit then return \"\"     end\n    \n    local Normal_prog, Heroic_prog, Mythic_prog = aura_env.getprogression() \n    \n    if Mythic_prog == nil and Heroic_prog == nil and Normal_prog == nil then return \"\" end\n    \n    if Mythic_prog ~= nil and Mythic_prog > 0 then \n        M_prog_string =  format(\"%s |c%s %s |r %s/8\\n\", name_string, aura_env.RAID_DIFFICULTY_COLORS[3][4], aura_env.RAID_DIFFICULTY_NAMES[3], Mythic_prog)\n    end\n    \n    if Heroic_prog ~= nil and Heroic_prog >= 0 then \n        H_prog_string =  format(\"%s |c%s %s |r  %s/8\\n\", name_string, aura_env.RAID_DIFFICULTY_COLORS[2][4], aura_env.RAID_DIFFICULTY_NAMES[2], Heroic_prog)\n    end\n    \n    if Normal_prog ~= nil and Normal_prog >= 0 and (Mythic_prog == 0) then \n        N_prog_string =  format(\"%s |c%s %s |r %s/8\\n\", name_string, aura_env.RAID_DIFFICULTY_COLORS[1][4], aura_env.RAID_DIFFICULTY_NAMES[1], Normal_prog)\n    end\n    \n    returnvalue = format(\"%s%s%s\", M_prog_string, H_prog_string, N_prog_string)\n    \n    return returnvalue\nend\n\naura_env.initializescore = function()\n    -- initialize button spacing.\n    local spacing = 3\n    local Width = region:GetWidth()\n    local Height = region:GetHeight()\n    local xDistance = Width + spacing    \n    local xOffset = 35 + (xDistance ) * 0 -- only for single button setups\n    local yOffset = 15\n    local ccsr_btn = _G[\"ccsr_btn\"] or CreateFrame(\"Frame\", \"ccsr_btn\", region)\n    local btnfont1 = _G[\"ccsr_btnfs1\"] or ccsr_btn:CreateFontString(\"ccsr_btnfs1\")\n    local textstring = aura_env.getraidstring() or \"\"\n    \n    local textoptions = charsheet.config.textoutline\n    \n    if textoptions == 1 then textoptions = \"\"\n    elseif textoptions == 2 then textoptions = \"OUTLINE\"\n    elseif textoptions == 3 then textoptions = \"THICKOUTLINE\"\n    end\n    \n    ccsr_btn:SetSize(Width, Height)\n    ccsr_btn:SetAllPoints()\n    ccsr_btn:SetFrameStrata(\"HIGH\")\n    ccsr_btn:Show()\n    \n    btnfont1:SetPoint(\"LEFT\", ccsr_btn, \"LEFT\", 0 ,0)\n    btnfont1:SetFont(LSM:Fetch(\"font\", charsheet.subRegions[2].text_font), (c.fontsize_raid or 11), textoptions)\n    btnfont1:SetText(textstring)\n    \n    if _G[\"ccsrf_sf\"] then\n        local Normal_prog, Heroic_prog, Mythic_prog = aura_env.getprogression()\n        \n        for x=1,8 do \n            local y\n            if tocversion < 110200 then y = x\n            elseif tocversion >= 110200 then y = x+10\n            end        \n            \n            if _G[\"ccsrf_b\"..x] then\n                if aura_env.bosscount(aura_env.SRI[y].normal) > 0 then\n                    _G[\"ccsrf_b\"..x..\"_fs1\"]:SetText(string.format(\"|cff1eff00%s|r\",aura_env.SRI[y].name))\n                    _G[\"ccsrf_b\"..x..\"_fs2\"]:SetText(string.format(\"%-2.2s\\n\", aura_env.bosscount(aura_env.SRI[y].normal)))\n                end\n                if aura_env.bosscount(aura_env.SRI[y].heroic) > 0 then\n                    _G[\"ccsrf_b\"..x..\"_fs3\"]:SetText(string.format(\"|cff0070dd%s|r\",aura_env.SRI[y].name))\n                    _G[\"ccsrf_b\"..x..\"_fs4\"]:SetText(string.format(\"%-2.2s\\n\", aura_env.bosscount(aura_env.SRI[y].heroic)))\n                end        \n                if aura_env.bosscount(aura_env.SRI[y].mythic) > 0 then\n                    _G[\"ccsrf_b\"..x..\"_fs5\"]:SetText(string.format(\"|cffa335ee%s|r\",aura_env.SRI[y].name))\n                    _G[\"ccsrf_b\"..x..\"_fs6\"]:SetText(string.format(\"%-2.2s\\n\", aura_env.bosscount(aura_env.SRI[y].mythic)))\n                end        \n            end\n        end\n        \n        _G[\"ccsrf_h_fs1\"]:SetText(string.format(\"|cff1eff00%s|r\\n(%s/8)\",PLAYER_DIFFICULTY1, Normal_prog))\n        _G[\"ccsrf_h_fs2\"]:SetText(string.format(\"|cff0070dd%s|r\\n(%s/8)\",PLAYER_DIFFICULTY2, Heroic_prog))\n        _G[\"ccsrf_h_fs3\"]:SetText(string.format(\"|cffa335ee%s|r\\n(%s/8)\",PLAYER_DIFFICULTY6, Mythic_prog))\n    end\n    \nend\n\naura_env.initializescore()\n\n-- Create the Raid Bosses Mouseover frame.\n\n-- Create the basic side frame\nlocal ccsrf_sf = _G[\"ccsrf_sf\"] or CreateFrame(\"Frame\", \"ccsrf_sf\", CharacterFrame, \"SecureHandlerBaseTemplate\");\nlocal rf_bg = _G[\"ccsrf_rf_bg\"] or ccsrf_sf:CreateTexture(\"ccsrf_rf_bg\", \"BACKGROUND\", nil, 1)        \nlocal rf_topbar = _G[\"ccsrf_rf_tb\"] or ccsrf_sf:CreateTexture(\"ccsrf_rf_tb\", \"BACKGROUND\", nil, 2)\nlocal rf_topstreaks = _G[\"ccsrf_rf_ts\"] or ccsrf_sf:CreateTexture(\"ccsrf_rf_ts\", \"BACKGROUND\", nil, 2)\nlocal rf_bottombar = _G[\"ccsrf_rf_bb\"] or ccsrf_sf:CreateTexture(\"ccsrf_rf_bb\", \"BACKGROUND\", nil, 2)\nlocal rf_box1 = _G[\"ccsrf_box1\"] or CreateFrame(\"Frame\", \"ccsrf_box1\", ccsrf_sf, \"BackdropTemplate\")\nlocal rf_box2 = _G[\"ccsrf_box2\"] or CreateFrame(\"Frame\", \"ccsrf_box2\", ccsrf_sf, \"BackdropTemplate\")\nlocal rf_box3 = _G[\"ccsrf_box3\"] or CreateFrame(\"Frame\", \"ccsrf_box3\", ccsrf_sf, \"BackdropTemplate\")    \n\nccsrf_sf:ClearAllPoints()\nccsrf_sf:SetPoint(\"TOPLEFT\", CharacterFrame, \"TOPRIGHT\", 63+charsheet.config.hpad, 0);\nccsrf_sf:SetPoint(\"BOTTOMLEFT\", CharacterFrame, \"BOTTOMRIGHT\", 63+charsheet.config.hpad, 0);    \nccsrf_sf:SetSize(900, 640)\nccsrf_sf:SetFrameStrata(\"TOOLTIP\")\n\nrf_bg:ClearAllPoints()\nrf_bg:SetAllPoints()\nrf_bg:SetTexture(\"Interface\\\\AddOns\\\\WeakAuras\\\\Media\\\\Textures\\\\Square_FullWhite.tga\")\nrf_bg:SetColorTexture(.12,.12,.12,1)\n\nrf_topbar:ClearAllPoints()\nrf_topbar:SetPoint(\"TOPLEFT\", ccsrf_sf, \"TOPLEFT\")\nrf_topbar:SetPoint(\"TOPRIGHT\", ccsrf_sf, \"TOPRIGHT\")\nrf_topbar:SetHeight(16)\nrf_topbar:SetTexture(\"1723833\")\nrf_topbar:SetTexCoord(0, 1, 0.586, .734)\n\nrf_topstreaks:ClearAllPoints()\nrf_topstreaks:SetPoint(\"TOPLEFT\", rf_topbar, \"BOTTOMLEFT\")\nrf_topstreaks:SetPoint(\"TOPRIGHT\", rf_topbar, \"BOTTOMRIGHT\")\nrf_topstreaks:SetHeight(43)\nrf_topstreaks:SetTexture(\"1723833\")\nrf_topstreaks:SetTexCoord(0, 1, 0, .328)\n\nrf_bottombar:ClearAllPoints()\nrf_bottombar:SetPoint(\"BOTTOMLEFT\", ccsrf_sf, \"BOTTOMLEFT\")\nrf_bottombar:SetPoint(\"BOTTOMRIGHT\", ccsrf_sf, \"BOTTOMRIGHT\")\nrf_bottombar:SetHeight(85)\n\nrf_bottombar:SetTexture(\"4556093\")\nrf_bottombar:SetTexCoord(0, .75, 0, .082) \n\nfor x=1,8 do \n    local ccsrf_bx = _G[\"ccsrf_b\"..x] or CreateFrame(\"Frame\", \"ccsrf_b\"..x, _G[\"ccsrf_sf\"]) --, \"SecureHandlerBaseTemplate\");\n    local height = 1;\n    \n    local y\n    if tocversion < 110200 then y = x\n    elseif tocversion >= 110200 then y = x+10\n    end\n    \n    ccsrf_bx:SetSize(840, 51*height)\n    ccsrf_bx:Show()\n    \n    local ccsrf_bx_tex1 = _G[\"ccsrf_b\"..x..\"_tex1\"] or ccsrf_bx:CreateTexture(\"ccsrf_b\"..x..\"_tex1\", \"BACKGROUND\", nil, 3)\n    ccsrf_bx_tex1:ClearAllPoints()\n    ccsrf_bx_tex1:SetAllPoints()\n    ccsrf_bx_tex1:SetTexture(\"Interface\\\\AddOns\\\\WeakAuras\\\\Media\\\\Textures\\\\Square_FullWhite.tga\")\n    \n    if x%2 == 1 then \n        ccsrf_bx_tex1:SetColorTexture(0, 0, 0, .4)\n    else\n        ccsrf_bx_tex1:SetColorTexture(.15, .15, .15, .6)\n    end\n    \n    ccsrf_bx_tex1:Show()\n    \n    -- Boss Icon\n    local ccsrf_bx_tex2 = _G[\"ccsrf_b\"..x..\"_tex2\"] or ccsrf_bx:CreateTexture(\"ccsrf_b\"..x..\"_tex2\", \"ARTWORK\", nil)\n    ccsrf_bx_tex2:SetPoint(\"TOPLEFT\", ccsrf_bx, \"TOPLEFT\", 5, -3)\n    ccsrf_bx_tex2:SetSize(90*height, 45*height)\n    ccsrf_bx_tex2:SetTexture(aura_env.SRI[y].icon)\n    ccsrf_bx_tex2:Show()\n    -- Boss Name Normal\n    local ccsrf_bx_fs1 = _G[\"ccsrf_b\"..x..\"_fs1\"] or  ccsrf_bx:CreateFontString(\"ccsrf_b\"..x..\"_fs1\")\n    ccsrf_bx_fs1:SetPoint(\"LEFT\", ccsrf_bx_tex2, \"RIGHT\", 10 ,0);\n    ccsrf_bx_fs1:SetFont(WA_Font, (c.bossfontsize or 14), textoptions);\n    ccsrf_bx_fs1:SetSize(200, 45*height)\n    ccsrf_bx_fs1:SetJustifyH(\"LEFT\")\n    if aura_env.bosscount(aura_env.SRI[y].normal) > 0 then\n        ccsrf_bx_fs1:SetText(string.format(\"|cff1eff00%s|r\",aura_env.SRI[y].name))\n    else\n        ccsrf_bx_fs1:SetText(string.format(\"|cff6b6c6e%s|r\",aura_env.SRI[y].name))            \n    end\n    ccsrf_bx_fs1:Show()\n    -- Kill Count Normal\n    local ccsrf_bx_fs2 = _G[\"ccsrf_b\"..x..\"_fs2\"] or  ccsrf_bx:CreateFontString(\"ccsrf_b\"..x..\"_fs2\")\n    ccsrf_bx_fs2:SetPoint(\"LEFT\", ccsrf_bx_tex2, \"RIGHT\", 230 ,0);\n    ccsrf_bx_fs2:SetFont(WA_Font, (c.bossfontsize or 14), textoptions);\n    ccsrf_bx_fs2:SetJustifyH(\"RIGHT\")\n    ccsrf_bx_fs2:SetText(string.format(\"%-2.2s\\n\", aura_env.bosscount(aura_env.SRI[y].normal)))\n    ccsrf_bx_fs2:Show()\n    -- Boss Name Heroic\n    local ccsrf_bx_fs3 = _G[\"ccsrf_b\"..x..\"_fs3\"] or  ccsrf_bx:CreateFontString(\"ccsrf_b\"..x..\"_fs3\")\n    ccsrf_bx_fs3:SetPoint(\"LEFT\", ccsrf_bx_tex2, \"RIGHT\", 260 ,0);\n    ccsrf_bx_fs3:SetFont(WA_Font, (c.bossfontsize or 14), textoptions);\n    ccsrf_bx_fs3:SetSize(200, 45*height)\n    ccsrf_bx_fs3:SetJustifyH(\"LEFT\")\n    if aura_env.bosscount(aura_env.SRI[y].heroic) > 0 then\n        ccsrf_bx_fs3:SetText(string.format(\"c%s|r\",aura_env.SRI[y].name))\n    else\n        ccsrf_bx_fs3:SetText(string.format(\"|cff6b6c6e%s|r\",aura_env.SRI[y].name))            \n    end\n    ccsrf_bx_fs3:Show()\n    -- Kill Count Heroic\n    local ccsrf_bx_fs4 = _G[\"ccsrf_b\"..x..\"_fs4\"