["trigger"] = {
["type"] = "custom",
["custom"] = "function(event, triggerNum, triggerStates)\n    if (event == \"TRIGGER\" or event == \"UNIT_THREAT_LIST_UPDATE\") then\n        aura_env.count = 0\n        for _,plate in pairs(C_NamePlate.GetNamePlates()) do\n            local unit = plate.namePlateUnitToken\n            if UnitAffectingCombat(unit) and UnitCanAttack(\"player\",unit) then\n                aura_env.count = aura_env.count + 1\n                if aura_env.count > 1 then\n                    return true\n                end\n            end\n        end\n        return false\n    end\nend\n\n",
