["custom"] = "function(allstates, event, arg1, arg2)\n    local aura_env = aura_env\n    \n    if event == \"PLAYER_EQUIPMENT_CHANGED\" then\n        -- This event is fired when an equipment slot is changed\n        if arg1 == nil then  return false end\n        aura_env.loopitems()\n        return true\n    elseif event == \"CCS_CSHOW\" then\n        aura_env.loopitems()\n        aura_env.ccs_cshow()        \n        return true        \n    elseif event == \"QUEST_ACCEPTED\" and arg1 and aura_env.Paragon_Factions[arg1] and C_Reputation.GetFactionDataByID(aura_env.Paragon_Factions[arg1].factionID) then\n        -- Checking for a Paragon Reward so we can toast\n        local name = C_Reputation.GetFactionDataByID(aura_env.Paragon_Factions[arg1].factionID).name\n        local text = GetQuestLogCompletionText(C_QuestLog.GetLogIndexForQuestID(arg1))\n        aura_env.ShowToast(name,text)\n    elseif CharacterFrame:IsVisible() then -- Rescan all item slots\n        aura_env.loopitems()\n        return true\n    end\nend",
