,.93)\n        CharacterWaistSlotIconTexture:SetTexCoord(.07,.07,.07,.93,.93,.07,.93,.93)\n        CharacterWristSlotIconTexture:SetTexCoord(.07,.07,.07,.93,.93,.07,.93,.93)\n        \n        CharacterBackSlotNormalTexture:Hide()\n        CharacterChestSlotNormalTexture:Hide()\n        CharacterFeetSlotNormalTexture:Hide()\n        CharacterFinger0SlotNormalTexture:Hide()\n        CharacterFinger1SlotNormalTexture:Hide()\n        CharacterHandsSlotNormalTexture:Hide()\n        CharacterHeadSlotNormalTexture:Hide()\n        CharacterLegsSlotNormalTexture:Hide()\n        CharacterMainHandSlotNormalTexture:Hide()\n        CharacterNeckSlotNormalTexture:Hide()\n        CharacterSecondaryHandSlotNormalTexture:Hide()\n        CharacterShirtSlotNormalTexture:Hide()\n        CharacterShoulderSlotNormalTexture:Hide()\n        CharacterTabardSlotNormalTexture:Hide()\n        CharacterTrinket0SlotNormalTexture:Hide()\n        CharacterTrinket1SlotNormalTexture:Hide()\n        CharacterWaistSlotNormalTexture:Hide()\n        CharacterWristSlotNormalTexture:Hide()\n        \n    end\n    \n    -- [Toast] Create Base Frame\n    local toast = _G[\"CCS_TOAST\"] or CreateFrame(\"FRAME\",\"CCS_TOAST\",UIParent)\n    toast:SetPoint(\"TOP\",UIParent,\"TOP\",0,-160)\n    toast:SetWidth(302)\n    toast:SetHeight(70)\n    toast:SetMovable(true)\n    toast:SetUserPlaced(false)\n    toast:SetClampedToScreen(true)\n    toast:RegisterForDrag(\"LeftButton\")\n    toast:SetScript(\"OnDragStart\",toast.StartMoving)\n    toast:SetScript(\"OnDragStop\",toast.StopMovingOrSizing)\n    toast:Hide()\n    toast.texture = toast:CreateTexture(nil,\"BACKGROUND\")\n    toast.texture:SetPoint(\"TOPLEFT\",toast,\"TOPLEFT\",-6,4)\n    toast.texture:SetPoint(\"BOTTOMRIGHT\",toast,\"BOTTOMRIGHT\",4,-4)\n    toast.texture:SetTexture(\"Interface\\\\Garrison\\\\GarrisonToast\")\n    toast.texture:SetTexCoord(0,.61,.33,.48)\n    toast.title = _G[\"CCS_TOASTfs1\"] or toast:CreateFontString(\"CCS_TOASTfs1\")\n    toast.title:SetPoint(\"TOPLEFT\",toast,\"TOPLEFT\",23,-10)\n    toast.title:SetWidth(260)\n    toast.title:SetHeight(16)\n    toast.title:SetJustifyV(\"TOP\")\n    toast.title:SetJustifyH(\"LEFT\")\n    toast.title:SetFont(WA_Font, 12, textoptions)\n    toast.title:Show()\n    toast.description = _G[\"CCS_TOASTfs2\"] or toast:CreateFontString(\"CCS_TOASTfs2\")\n    toast.description:SetPoint(\"TOPLEFT\",toast.title,\"TOPLEFT\",1,-23)\n    toast.description:SetWidth(258)\n    toast.description:SetHeight(32)\n    toast.description:SetJustifyV(\"TOP\")\n    toast.description:SetJustifyH(\"LEFT\")\n    toast.description:SetFont(WA_Font, 12, textoptions)\n    toast.description:Show()\n    toast.description:Show()\n    \n    CharacterFrame:SetScale(scaling); \n    ReputationFrame:SetScale(scaling);\n    ReputationFrame:ClearAllPoints()\n    ReputationFrame:SetPoint(\"TOPLEFT\", CharacterFrame, \"TOPLEFT\", 0, 0)\n    ReputationFrame:SetPoint(\"BOTTOMRIGHT\", CharacterFrameBg, \"BOTTOMRIGHT\", 0, 0)\n    ReputationFrame.ScrollBox:ClearAllPoints()\n    ReputationFrame.ScrollBox:SetPoint(\"TOPLEFT\", CharacterFrameInset, \"TOPLEFT\", 4, -4)\n    ReputationFrame.ScrollBox:SetPoint(\"BOTTOMRIGHT\", CharacterFrameInset.Bg, \"BOTTOMRIGHT\", 80, 0)\n    ReputationFrame.filterDropdown:ClearAllPoints()\n    ReputationFrame.filterDropdown:SetPoint(\"TOPRIGHT\", ReputationFrame, \"TOPRIGHT\", -38, -30)    \n    TokenFrame:SetScale(scaling); \n    TokenFrame:ClearAllPoints()\n    TokenFrame:SetPoint(\"TOPLEFT\", CharacterFrame, \"TOPLEFT\", 0, 0)\n    TokenFrame:SetPoint(\"BOTTOMRIGHT\", CharacterFrameBg, \"BOTTOMRIGHT\", 0, 0)\n    TokenFrame.ScrollBox:ClearAllPoints()\n    TokenFrame.ScrollBox:SetPoint(\"TOPLEFT\", CharacterFrameInset, \"TOPLEFT\", 4, -4)\n    TokenFrame.ScrollBox:SetPoint(\"BOTTOMRIGHT\", CharacterFrameInset.Bg, \"BOTTOMRIGHT\", 80, 0)\n    \n    if ccs_sf then ccs_sf:SetScale(.69); end\n    \n    -- Create the character model button\n    modelbtn:SetSize(23, 23)\n    modelbtn:SetPoint(\"BOTTOMLEFT\", PaperDollItemsFrame, \"BOTTOMLEFT\", xOffset, yOffset)\n    modelbtn:SetFrameStrata(\"HIGH\")\n    modelbtn:Show()\n    \n    local modelbtnfont1 = _G[\"CCS_clk_Btnfs1\"] or modelbtn:CreateFontString(\"CCS_clk_Btnfs1\")\n    \n    modelbtnfont1:SetPoint(\"BOTTOM\", modelbtn, \"TOP\", -3 , 2)\n    modelbtnfont1:SetFont(LSM:Fetch(\"font\", charsheet.subRegions[2].text_font), (c.fontsize_showchar or 10), \"OUTLINE\")\n    modelbtnfont1:SetText(MOUNT_JOURNAL_PLAYER)\n    modelbtnfont1:SetWordWrap(true)\n    modelbtn:SetNormalTexture(\"Interface\\\\Calendar\\\\MeetingIcon.blp\")\n    modelbtn:SetScript(\"OnEnter\", function() GameTooltip:SetOwner(UIParent, \"ANCHOR_CURSOR\")\n            GameTooltip:AddDoubleLine(\"\", nil, 1, 1, 1, 1, 1, 1) \n            GameTooltip:Show()\n    end)\n    modelbtn:SetScript(\"OnLeave\", function() GameTooltip:Hide() end)\n    modelbtn:SetScript(\"OnClick\", function()\n            if not InCombatLockdown() then \n                aura_env.Clicky(1) \n            else\n                RaidNotice_AddMessage(RaidBossEmoteFrame, format(\"%s\", ERR_AFFECTING_COMBAT), ChatTypeInfo[\"SYSTEM\"])\n            end \n    end)\n    \n    modbg:ClearAllPoints()\n    modbg:SetPoint(\"TOPLEFT\", CharacterHeadSlot, \"TOPLEFT\", 0, 0)\n    modbg:SetPoint(\"RIGHT\", CharacterHandsSlot, \"RIGHT\", 0, 0)    \n    modbg:SetPoint(\"BOTTOM\", CharacterMainHandSlot, \"BOTTOM\", 0, 0)        \n    modbg:SetFrameStrata(\"LOW\")\n    modbg:SetFrameLevel(50)\n    modtex:ClearAllPoints()\n    modtex:SetAllPoints()\n    modtex:SetTexture(\"Interface\\\\MOTHER_TalentTree\\\\MOTHERtalenttree.BLP\")    \n    modtex:SetTexCoord(0, .69, 0, .87)\n    modtex:SetVertexColor(.4,0,.4,.9);\n    if c.hidemodelbg then\n        modbg:Hide()\n    else\n        modbg:Show()\n    end\n    \n    local Height = 520  -- Hard code it for now\n    local Left = 120  -- Hard code it for now\n    \n    CharacterModelScene:ClearAllPoints();\n    CharacterModelScene:SetHeight(Height)\n    CharacterModelScene:SetWidth(Height/ModelAspect)\n    CharacterModelScene:SetPoint(\"LEFT\", CharacterFrameBg, \"LEFT\", Left, -20);\n    CharacterModelScene:SetFrameLevel(2)\n    CharacterModelScene:Show();\n    CharacterModelFrameBackgroundTopLeft:Hide();\n    CharacterModelFrameBackgroundBotLeft:Hide();\n    CharacterModelFrameBackgroundTopRight:Hide();\n    CharacterModelFrameBackgroundBotRight:Hide();\n    CharacterModelFrameBackgroundOverlay:ClearAllPoints()\n    CharacterModelFrameBackgroundOverlay:SetPoint(\"TOPLEFT\", CharacterModelFrameBackgroundTopLeft, \"TOPLEFT\", 0, 0)\n    CharacterModelFrameBackgroundOverlay:SetPoint(\"BOTTOMRIGHT\", CharacterModelFrameBackgroundBotRight, \"BOTTOMRIGHT\", 0, 70)\n    CharacterModelFrameBackgroundOverlay:Hide()\nend\n\naura_env.initializecharacterframe()\n\naura_env.ReputationFrame_Update = function()\n    local ks={ReputationFrame.ScrollBox.ScrollTarget:GetChildren()}; \n    local gender = UnitSex(\"player\");\n    local xtext, factiontext= \"\", \"\"\n    \n    if C_AddOns.IsAddOnLoaded(\"PrettyReps\") then return end\n    \n    for _,k in ipairs(ks) do -- Individual Row\n        local factionData = C_Reputation.GetFactionDataByIndex(k.factionIndex)\n        local ks2={k:GetChildren()}; \n        if factionData ~= nil then\n            for _,k2 in ipairs(ks2) do  -- Reputation Bar (in the row)\n                local factionID = factionData.factionID\n                local name =  factionData.name\n                local standingID =  factionData.reaction\n                local barMin =  factionData.currentReactionThreshold\n                local barMax =  factionData.nextReactionThreshold\n                local barValue =  factionData.currentStanding\n                \n                k2.Background = k2.Background or k2:CreateTexture(nil, \"BACKGROUND\", nil, 2)\n                \n                if (k2.Background) then\n                    k2.Background:SetTexture(\"Interface\\\\AddOns\\\\WeakAuras\\\\Media\\\\Textures\\\\Square_FullWhite.tga\")\n                    k2.Background:SetColorTexture(.15, .15, .15, 0.90)\n                    k2.Background:SetPoint(\"TOPLEFT\", k2, \"TOPLEFT\")\n                    k2.Background:SetPoint(\"BOTTOMRIGHT\", k2, \"BOTTOMRIGHT\")                \n                end\n                \n                if (k2.ReputationBar) then\n                    k2.ReputationBar.LeftTexture:SetTexture(\"Interface\\\\AddOns\\\\WeakAuras\\\\Media\\\\Textures\\\\Square_FullWhite.tga\")\n                    k2.ReputationBar.LeftTexture:SetGradient(\"Vertical\", CreateColor(0, 0, 0, .2), CreateColor(.2, .2, .2, .4)) -- Dark Gray\n                    k2.ReputationBar.LeftTexture:SetAlpha(0.9)\n                    k2.ReputationBar.LeftTexture:SetPoint(\"RIGHT\", k2, \"RIGHT\")\n                    k2.ReputationBar:SetWidth(202)\n                    k2.ReputationBar:SetHeight(k2:GetHeight()*.9)            \n                    k2.ReputationBar.RightTexture:Hide()\n                end\n                \n                if name == \"Inactive\" or name == \"Other\" then\n                    -- we skip the inactive header since the friendship lookup doesn't like it.\n                else\n                    local friendID, friendRep, friendMaxRep, friendName, friendText, friendTexture, friendTextLevel, friendThreshold, nextFriendThreshold = C_GossipInfo.GetFriendshipReputation(factionID);\n                    local colorIndex = standingID;\n                    local barColor = FACTION_BAR_COLORS[colorIndex];\n                    local factionStandingtext;\n                    local isCapped = (standingID == MAX_REPUTATION_REACTION)\n                    local isParagon = factionID and C_Reputation.IsFactionParagon(factionID);\n                    local isMajorFaction = factionID and C_Reputation.IsMajorFaction(factionID);\n                    local repInfo = factionID and C_GossipInfo.GetFriendshipReputation(factionID);\n                    \n                    if (repInfo and repInfo.friendshipFactionID > 0) then\n                        factionStandingtext = repInfo.reaction;\n                        if ( repInfo.nextThreshold ) then\n                            barMin, barMax, barValue = repInfo.reactionThreshold, repInfo.nextThreshold, repInfo.standing;\n                        else\n                            barMin, barMax, barValue = 0, 1, 1;\n                            isCapped = true;\n                        end\n                        local friendshipColorIndex = 5;\n                        barColor = FACTION_BAR_COLORS[colorIndex];\n                        k2.friendshipID = repInfo.friendshipFactionID;  \n                    elseif ( isMajorFaction ) then\n                        local majorFactionData = C_MajorFactions.GetMajorFactionData(factionID);\n                        \n                        barMin, barMax = 0, majorFactionData.renownLevelThreshold;\n                        isCapped = C_MajorFactions.HasMaximumRenown(factionID);\n                        barValue = isCapped and majorFactionData.renownLevelThreshold or majorFactionData.renownReputationEarned or 0;\n                        barColor = BLUE_FONT_COLOR;\n                        \n                        k2.friendshipID = nil;\n                        factionStandingtext = string.format(RENOWN_LEVEL_LABEL, majorFactionData.renownLevel);\n                    else\n                        factionStandingtext = GetText(\"FACTION_STANDING_LABEL\"..standingID, gender);\n                        k2.friendshipID = nil;\n                    end\n                    \n                    factiontext = factionStandingtext;\n                    \n                    if isCapped and (not repInfo or repInfo.friendshipFactionID == 0) then\n                        barMax = 21000;\n                        barValue = 21000;\n                        barMin = 0;\n                    else\n                        barMax = barMax - barMin;\n                        barValue = barValue - barMin;\n                        barMin = 0;\n                    end\n                    \n                    if factionID and C_Reputation.IsFactionParagon(factionID) and k2.ParagonIcon then\n                        local currentValue,threshold,rewardQuestID,hasRewardPending = C_Reputation.GetFactionParagonInfo(factionID)\n                        local r,g,b = 0,.5,.9\n                        \n                        factiontext = PARAGON_STRING\n                        barMax = threshold\n                        barValue = currentValue - (floor(currentValue/threshold)-(hasRewardPending and 1 or 0))*threshold \n                        barMin = 0\n                        k2.ParagonIcon:SetShown(hasRewardPending); \n                        k2.ReputationBar:SetStatusBarColor(r,g,b)\n                        k2.ReputationBar:SetMinMaxValues(0, barMax);\n                        k2.ReputationBar:SetValue(barValue);\n                        \n                    end\n                    \n                    if (k2.ReputationBar) then\n                        local fontName, fontHeight, fontFlags = k2.ReputationBar.BarText:GetFont()\n                        xtext = format(\"  %s%-17.17s %15.15s%s\", HIGHLIGHT_FONT_COLOR_CODE, factiontext, format(REPUTATION_PROGRESS_FORMAT, BreakUpLargeNumbers(barValue), BreakUpLargeNumbers(barMax)), FONT_COLOR_CODE_CLOSE)\n                        k2.ReputationBar.barProgressText = xtext\n                        k2.ReputationBar.reputationStandingText = xtext\n                        k2.ReputationBar.BarText:SetFont(fontName, c.fontsize_reputation, textoptions)\n                        k2.Name:SetFont(fontName, c.fontsize_reputation, textoptions)\n                        k2.ReputationBar.BarText:SetText(xtext)                \n                        k2.ReputationBar.BarText:ClearAllPoints()\n                        k2.ReputationBar.BarText:SetPoint(\"LEFT\", k2.ReputationBar, \"LEFT\")\n                    end\n                    \n                    if (k2.AccountWideIcon) then\n                        k2.awi = k2.awi or k2:CreateTexture(nil, \"OVERLAY\", nil, 2)\n                        k2.awi:SetSize(23, 23)\n                        k2.awi:SetAtlas(\"warbands-icon\", true)\n                        k2.awi:SetScale(0.9)\n                        k2.awi:ClearAllPoints()\n                        k2.awi:SetPoint(\"TOPLEFT\", k2.AccountWideIcon, \"TOPLEFT\")\n                        k2.awi:SetPoint(\"BOTTOMRIGHT\", k2.AccountWideIcon, \"BOTTOMRIGHT\")\n                        k2.awi:SetShown(C_Reputation.IsAccountWideReputation(factionID))\n                    end \n                end \n                \n                \n            end \n        end\n    end\nend\n\naura_env.InitializeFrameUpdates = function()\n    PaperDollFrame.TitleManagerPane:ClearAllPoints()\n    PaperDollFrame.TitleManagerPane:SetPoint(\"TOPLEFT\", CharacterFrameInsetRight, \"TOPLEFT\", 9, -4)\n    PaperDollFrame.TitleManagerPane:SetPoint(\"BOTTOM\", CharacterFrameInsetRight, \"BOTTOM\", 0, 10)\n    PaperDollFrame.TitleManagerPane.ScrollBox:ClearAllPoints()\n    PaperDollFrame.TitleManagerPane.ScrollBox:SetPoint(\"TOPLEFT\", CharacterFrameInsetRight, \"TOPLEFT\", 9, -4)\n    PaperDollFrame.TitleManagerPane.ScrollBox:SetPoint(\"BOTTOM\", CharacterFrameInsetRight, \"BOTTOM\", 0, 10)\n    \n    PaperDollFrame.EquipmentManagerPane:ClearAllPoints()\n    PaperDollFrame.EquipmentManagerPane:SetPoint(\"TOPLEFT\", CharacterFrameInsetRight, \"TOPLEFT\", 9, -4)\n    PaperDollFrame.EquipmentManagerPane:SetPoint(\"BOTTOM\", CharacterFrameInsetRight, \"BOTTOM\", 0, 10)\n    PaperDollFrame.EquipmentManagerPane.ScrollBox:ClearAllPoints()\n    PaperDollFrame.EquipmentManagerPane.ScrollBox:SetPoint(\"TOPLEFT\", PaperDollFrameEquipSet, \"BOTTOMLEFT\", 9, 0)\n    --PaperDollFrame.EquipmentManagerPane.ScrollBox:SetPoint(\"TOPLEFT\", CharacterFrameInsetRight, \"TOPLEFT\", 9, -4)\n    PaperDollFrame.EquipmentManagerPane.ScrollBox:SetPoint(\"BOTTOM\", CharacterFrameInsetRight, \"BOTTOM\", 0, 10)\n    \n    ReputationFrame:ClearAllPoints()\n    ReputationFrame:SetPoint(\"TOPLEFT\", CharacterFrameBg, \"TOPLEFT\", 0, 0)\n    ReputationFrame:SetPoint(\"BOTTOMRIGHT\", CharacterFrameBg, \"BOTTOMRIGHT\", 0, 0)\n    _G[\"CCSf\"]:Hide()\n    _G[\"ccs_sf\"]:Hide()\nend\n\nif not _G[\"ccs_sf\"] then \n    \n    if not _G[\"CCSf\"] then CreateFrame(\"Frame\", \"CCSf\", CharacterFrame) end\n    local ccsf_af = _G[\"ccsf_af\"] or CreateFrame(\"Frame\", \"ccsf_af\", CharacterFrame, \"SecureHandlerBaseTemplate\");\n    \n    \n    ccsf_af:ClearAllPoints()\n    ccsf_af:SetPoint(\"TOPLEFT\", CharacterFrame, \"TOPRIGHT\",  c.hpad+63, 0);\n    CCSf:ClearAllPoints(); \n    CCSf:SetPoint(\"TOPLEFT\", ccsf_af, \"TOPRIGHT\", 0, 0); \n    CCSf:SetSize(900, 640)\n    CCSf:Hide()\n    \n    CharacterFrameCloseButton:SetScale(.7)\n    \n    local sf = _G[\"ccs_sf\"] or CreateFrame(\"Frame\", \"ccs_sf\", CharacterFrame);\n    local sf_bg = _G[\"ccs_sf_bg\"] or sf:CreateTexture(\"ccs_sf_bg\", \"BACKGROUND\", nil, 1)        \n    local sf_topbar = _G[\"ccs_sf_tb\"] or sf:CreateTexture(\"ccs_sf_tb\", \"BACKGROUND\", nil, 2)\n    local sf_topstreaks = _G[\"ccs_sf_ts\"] or sf:CreateTexture(\"ccs_sf_ts\", \"BACKGROUND\", nil, 2)\n    local sf_bottombar = _G[\"ccs_sf_bb\"] or sf:CreateTexture(\"ccs_sf_bb\", \"BACKGROUND\", nil, 2)\n    \n    sf:SetScale(.69)\n    sf_bg:Show()\n    \n    --== Frame Hooks\n    if C_AddOns.IsAddOnLoaded(\"PrettyReps\") == false then\n        hooksecurefunc(ReputationFrame, \"Hide\", function() ReputationFrame.ReputationDetailFrame:Hide(); end )\n        hooksecurefunc(ReputationFrame.ScrollBox, \"Update\", aura_env.ReputationFrame_Update)\n        hooksecurefunc(ReputationFrame.ReputationDetailFrame, \"Show\", aura_env.ReputationFrame_Update)\n        hooksecurefunc(ReputationFrame.ReputationDetailFrame, \"Hide\", aura_env.ReputationFrame_Update)\n        hooksecurefunc(ReputationFrame, \"Show\", function() \n                aura_env.hookfix();\n                aura_env.InitializeFrameUpdates();\n        end)\n    end\n    hooksecurefunc(TokenFrame, \"Show\", function() aura_env.hookfix(); end)\n    hooksecurefunc(TokenFrame.ScrollBox, \"Update\", function() \n            \n            local tf={TokenFrame.ScrollBox.ScrollTarget:GetChildren()}; \n            \n            for _,t in ipairs(tf) do \n                if t and t.Name then t.Name:SetFont(t.Name:GetFont(), c.fontsize_currency or 11, \"\")end \n                if t and t.Count then t.Count:SetFont(t.Count:GetFont(), c.fontsize_currency or 11, \"\")end \n                \n                local ks2={t:GetChildren()}; \n                for _,k2 in ipairs(ks2) do  -- Individual Row\n                    k2.Background = k2.Background or k2:CreateTexture(nil, \"BACKGROUND\", nil, 2)\n                    \n                    if (k2.Background) then\n                        k2.Background:SetTexture(\"Interface\\\\AddOns\\\\WeakAuras\\\\Media\\\\Textures\\\\Square_FullWhite.tga\")\n                        k2.Background:SetColorTexture(.15, .15, .15, 0.90)\n                        k2.Background:ClearAllPoints()\n                        k2.Background:SetPoint(\"TOPLEFT\", k2, \"TOPLEFT\")\n                        k2.Background:SetPoint(\"BOTTOMRIGHT\", k2, \"BOTTOMRIGHT\")\n                        k2.Background:Show()\n                    end\n                    \n                    if k2.AccountWideIcon then\n                        k2.awi = k2.awi or k2:CreateTexture(nil, \"OVERLAY\", nil, 2)\n                        k2.awi:SetSize(23, 23)\n                        k2.awi:SetAtlas(\"warbands-icon\", true)\n                        k2.awi:SetScale(0.9)\n                        k2.awi:ClearAllPoints()\n                        k2.awi:SetPoint(\"TOPLEFT\", k2.AccountWideIcon, \"TOPLEFT\")\n                        k2.awi:SetPoint(\"BOTTOMRIGHT\", k2.AccountWideIcon, \"BOTTOMRIGHT\")\n                        if t.elementData.isAccountTransferable then\n                            k2.awi:Show()\n                        else\n                            k2.awi:Hide()\n                        end\n                        \n                    end \n                end\n                \n            end\n            \n    end)\n    \n    hooksecurefunc(PaperDollFrame, \"Show\", function() aura_env.hookfix(); end)\n    \n    hooksecurefunc(CharacterFrame, \"Show\", function() \n            aura_env.InitializeFrameUpdates(); \n            aura_env.loopitems();\n            \n            sf:ClearAllPoints()\n            sf:SetPoint(\"TOPLEFT\", CCSf, \"TOPLEFT\", 0, 0); \n            sf:SetPoint(\"TOPRIGHT\", CCSf, \"TOPRIGHT\", 0, 0);\n            sf:SetPoint(\"BOTTOM\", CCSf, \"BOTTOM\", 0, 0);\n            \n            local bgr, bgg, bgb, bgalpha = c.ccsbgcolor[1], c.ccsbgcolor[2], c.ccsbgcolor[3], c.ccsbgcolor[4];\n            sf_bg:ClearAllPoints()\n            sf_bg:SetAllPoints()\n            sf_bg:SetTexture(\"Interface\\\\AddOns\\\\WeakAuras\\\\Media\\\\Textures\\\\Square_FullWhite.tga\")\n            sf_bg:SetColorTexture(bgr,bgg,bgb,bgalpha)\n            \n            sf_topbar:ClearAllPoints()\n            sf_topbar:SetPoint(\"TOPLEFT\", sf, \"TOPLEFT\")\n            sf_topbar:SetPoint(\"TOPRIGHT\", sf, \"TOPRIGHT\")\n            sf_topbar:SetHeight(16)\n            sf_topbar:SetTexture(\"1723833\")\n            sf_topbar:SetTexCoord(0, 1, 0.586, .734)\n            \n            sf_topstreaks:ClearAllPoints()\n            sf_topstreaks:SetPoint(\"TOPLEFT\", sf_topbar, \"BOTTOMLEFT\")\n            sf_topstreaks:SetPoint(\"TOPRIGHT\", sf_topbar, \"BOTTOMRIGHT\")\n            sf_topstreaks:SetHeight(43)\n            sf_topstreaks:SetTexture(\"1723833\")\n            sf_topstreaks:SetTexCoord(0, 1, 0, .328)\n            sf_bottombar:ClearAllPoints()\n            sf_bottombar:SetPoint(\"BOTTOMLEFT\", sf, \"BOTTOMLEFT\")\n            sf_bottombar:SetPoint(\"BOTTOMRIGHT\", sf, \"BOTTOMRIGHT\")\n            sf_bottombar:SetHeight(67)\n            sf_bottombar:SetTexture(\"4556093\")\n            sf_bottombar:SetTexCoord(0, .75, 0, .082) \n            WeakAuras.ScanEvents(\"CCS_CSHOW\")\n            WeakAuras.ScanEvents(\"CCS_STATS\")            \n            GameTooltip:Hide()\n            aura_env.hookfix()\n            \n            if C_AddOns.IsAddOnLoaded(\"NDui\") then\n                CharacterFrameCloseButton:Hide()\n            end\n    end )\n    \n    hooksecurefunc(CharacterFrame, \"Hide\", function() GameTooltip:Hide(); end )\n    \nelseif C_AddOns.IsAddOnLoaded(\"PrettyReps\") == false then\n    hooksecurefunc(ReputationFrame, \"Show\", function() aura_env.InitializeFrameUpdates(); end)\n    hooksecurefunc(ReputationFrame, \"Hide\", function() ReputationFrame.ReputationDetailFrame:Hide(); end)\n    hooksecurefunc(ReputationFrame.ScrollBox, \"Update\", aura_env.ReputationFrame_Update)\n    hooksecurefunc(ReputationFrame.ReputationDetailFrame, \"Show\", aura_env.ReputationFrame_Update)\n    hooksecurefunc(ReputationFrame.ReputationDetailFrame, \"Hide\", aura_env.ReputationFrame_Update)\nend\n\n-- Show the Paragon Toast if a Paragon Reward Quest is accepted.\naura_env.ShowToast = function (name,text)\n    local toast = _G[\"CCS_TOAST\"]\n    \n    PlaySound(44295,\"master\",true)\n    \n    if (not toast:IsVisible()) then\n        toast:EnableMouse(false)\n        toast.title:SetText(name)\n        toast.title:SetAlpha(0)\n        toast.description:SetText(text)\n        toast.description:SetAlpha(0)\n        C_Timer.After(1, function() UIFrameFadeIn(toast,.5,0,1)    end)\n        C_Timer.After(2, function() UIFrameFadeIn(toast.title,.5,0,1)    end)\n        C_Timer.After(2, function() UIFrameFadeIn(toast.description,.5,0,1)    end)\n        C_Timer.After(5, function() UIFrameFadeOut(toast,1,1,0)    end)\n    end\nend\n\naura_env.getLocationLink = function(location)\n    if location:IsEquipmentSlot() then\n        return GetInventoryItemLink(\"player\", location:GetEquipmentSlot())\n    else\n        return nil\n    end\nend\n\naura_env.getSlotFrameName = function(location)\n    \n    if location:IsEquipmentSlot() then\n        local slotIndex = location:GetEquipmentSlot()\n        local slotName=\"\"\n        \n        if slotIndex == 1 then slotName = \"Head\"\n        elseif slotIndex == 2 then slotName = \"Neck\"\n        elseif slotIndex == 3 then slotName = \"Shoulder\"\n        elseif slotIndex == 4 then slotName = \"Shirt\"    \n        elseif slotIndex == 5 then slotName = \"Chest\"\n        elseif slotIndex == 6 then slotName = \"Waist\"\n        elseif slotIndex == 7 then slotName = \"Legs\"\n        elseif slotIndex == 8 then slotName = \"Feet\"\n        elseif slotIndex == 9 then slotName = \"Wrist\"\n        elseif slotIndex == 10 then slotName = \"Hands\"\n        elseif slotIndex == 11 then slotName = \"Finger0\"\n        elseif slotIndex == 12 then slotName = \"Finger1\"\n        elseif slotIndex == 13 then slotName = \"Trinket0\"\n        elseif slotIndex == 14 then slotName = \"Trinket1\"\n        elseif slotIndex == 15 then slotName = \"Back\"\n        elseif slotIndex == 16 then slotName = \"MainHand\"\n        elseif slotIndex == 17 then slotName = \"SecondaryHand\"\n        elseif slotIndex == 19 then slotName = \"Tabard\"\n        else return nil\n        end\n        \n        return \"Character\"..slotName..\"Slot\"\n    else\n        return nil\n    end\nend\n\n-- Return True if the item is on the left (text block on the right)\naura_env.leftitemdisplay = function(eslot)\n    if eslot == 10 or eslot == 6 or eslot == 7 or eslot == 8 or eslot == 11 or eslot == 12 or eslot == 13 or eslot == 14 or eslot == 16 then\n        return true\n    end\n    return false\nend\n\naura_env.initializecharacterframe()\n\naura_env.updateLocationInfo = function (slotIndex)\n    local slotItem = ItemLocation:CreateFromEquipmentSlot(slotIndex) -- item \"location\"\n    local link = aura_env.getLocationLink(slotItem)\n    local slotFrameName = aura_env.getSlotFrameName(slotItem)\n    local leftdisplay = aura_env.leftitemdisplay(slotIndex)\n    local SubElementSetPoint = \"LEFT\"\n    local SubElementSetPoint2 = \"RIGHT\"\n    local neg = 1\n    local Width = region:GetWidth()\n    local Height = region:GetHeight()\n    \n    if leftdisplay then \n        SubElementSetPoint = \"RIGHT\" \n        SubElementSetPoint2 = \"LEFT\" \n        neg = -1\n    end\n    \n    if slotFrameName == nil or slotIndex == 18 then return end  \n    \n    local nameTxt = _G[slotFrameName..\"namefs\"] or _G[slotFrameName]:CreateFontString(slotFrameName..\"namefs\")\n    local ilvlTxt = _G[slotFrameName..\"ilvlfs\"] or _G[slotFrameName]:CreateFontString(slotFrameName..\"ilvlfs\")\n    local enchantTxt = _G[slotFrameName..\"enchantfs\"] or _G[slotFrameName]:CreateFontString(slotFrameName..\"enchantfs\")\n    local durabilityTxt = _G[slotFrameName..\"durabilityfs\"] or _G[slotFrameName]:CreateFontString(slotFrameName..\"durabilityfs\")\n    local durbar = _G[slotFrameName..\"durbar\"] or CreateFrame(\"Frame\", slotFrameName..\"durbar\", _G[slotFrameName])\n    local durbartex = _G[durbar:GetName()..\"tex\"] or durbar:CreateTexture(durbar:GetName()..\"tex\", \"BACKGROUND\", nil, 2)\n    local bgfader = _G[slotFrameName..\"bgfader\"] or CreateFrame(\"Frame\", slotFrameName..\"bgfader\", _G[slotFrameName])\n    local bgfadertex = _G[bgfader:GetName()..\"tex\"] or bgfader:CreateTexture(bgfader:GetName()..\"tex\", \"BACKGROUND\", nil, 1)\n    local gemIconframe1 = _G[slotFrameName..\"gemtex1\"] or CreateFrame(\"Button\", slotFrameName..\"gemtex1\", _G[slotFrameName], \"UIPanelButtonTemplate\")\n    local gemIconframe2 = _G[slotFrameName..\"gemtex2\"] or CreateFrame(\"Button\", slotFrameName..\"gemtex2\", _G[slotFrameName], \"UIPanelButtonTemplate\")\n    local gemIconframe3 = _G[slotFrameName..\"gemtex3\"] or CreateFrame(\"Button\", slotFrameName..\"gemtex3\", _G[slotFrameName], \"UIPanelButtonTemplate\")\n    \n    nameTxt:SetPoint(SubElementSetPoint, _G[slotFrameName], SubElementSetPoint2, 10 * neg, 13)\n    nameTxt:SetFont(WA_Font, (c.fontsize_iname or 11) , textoptions)\n    ilvlTxt:SetPoint(SubElementSetPoint, _G[slotFrameName], SubElementSetPoint2, 10 * neg, 0) \n    ilvlTxt:SetFont(WA_Font, (c.fontsize_ilvl or 10), textoptions)\n    enchantTxt:SetPoint(SubElementSetPoint, _G[slotFrameName], SubElementSetPoint2, 10 * neg, -13)\n    enchantTxt:SetFont(WA_Font, (c.fontsize_enchant or 10), textoptions)\n    durabilityTxt:SetPoint(\"CENTER\", _G[slotFrameName], \"CENTER\", 0, 0)\n    durabilityTxt:SetFont(WA_Font, (c.fontsize_durability or 10), textoptions)\n    durbar:SetSize(4, 34)\n    durbar:SetPoint(\"BOTTOM\"..SubElementSetPoint, slotFrameName, \"BOTTOM\"..SubElementSetPoint2, 1 * neg, 0)\n    durbar:SetFrameLevel(2)\n    durbartex:SetAllPoints()\n    durbartex:SetTexture(\"Interface\\\\AddOns\\\\WeakAuras\\\\Media\\\\Textures\\\\Square_FullWhite.tga\")\n    \n    bgfader:SetSize(240, 39) -- fader size (scales with the character frame)\n    bgfader:SetPoint(SubElementSetPoint, slotFrameName, SubElementSetPoint2, -38 * neg, 0)        \n    bgfader:SetFrameLevel(1)\n    bgfadertex:SetAllPoints()\n    bgfadertex:SetTexture(\"Interface\\\\AddOns\\\\WeakAuras\\\\Media\\\\Textures\\\\Square_AlphaGradient.tga\")\n    \n    gemIconframe1:SetSize(Width, Height)\n    gemIconframe1:SetPoint(\"TOP\"..SubElementSetPoint2, slotFrameName, \"TOP\"..SubElementSetPoint, -8 * neg, 6)\n    gemIconframe1:SetFrameStrata(\"HIGH\")\n    \n    gemIconframe2:SetSize(Width, Height)\n    gemIconframe2:SetPoint(SubElementSetPoint2, slotFrameName, SubElementSetPoint, -8 * neg, 0)\n    gemIconframe2:SetFrameStrata(\"HIGH\")\n    \n    gemIconframe3:SetSize(Width, Height)\n    gemIconframe3:SetPoint(\"BOTTOM\"..SubElementSetPoint2, slotFrameName, \"BOTTOM\"..SubElementSetPoint, -8 * neg, -6)\n    gemIconframe3:SetFrameStrata(\"HIGH\")\n    \n    nameTxt:Hide()\n    ilvlTxt:Hide()\n    enchantTxt:Hide()\n    durabilityTxt:Hide()\n    gemIconframe1:Hide()\n    gemIconframe2:Hide()\n    gemIconframe3:Hide()    \n    bgfader:Hide()\n    durbar:Hide()\n    \n    if slotItem == nil or link == nil then \n        nameTxt:SetText(\"\")\n        ilvlTxt:SetText(\"\")\n        enchantTxt:SetText(\"\")\n        durabilityTxt:SetText(\"\")\n    else \n        local durCur, durMax = GetInventoryItemDurability(slotIndex)\n        local _, _, _, _, _, _, Gem1, Gem2, Gem3, _, _, _, _, _, _ = string.find(link, \"|?c?f?f?(%x*)|?H?([^:]*):?(%d+):?(%d*):?(%d*):?(%d*):?(%d*):?(%d*):?(%-?%d*):?(%-?%d*):?(%d*):?(%d*)|?h?%[?([^%[%]]*)%]?|?h?|?r?\")\n        local itemName, _, itemRarity, itemiLevel, _, itemType, _, _, _, _, _, _, _, _, expacID, setID, _ = C_Item.GetItemInfo(link)\n        local Color = \"ffffffff\"\n        \n        if itemRarity and itemRarity >= 1 and itemRarity <= 7 then\n            Color = select(4, C_Item.GetItemQualityColor(itemRarity))\n        end\n        \n        local Gemtex1, Gemtex2, Gemtex3 = nil, nil, nil\n        local ItemTip = _G[\"CCS_Scanningtooltip\"] or CreateFrame('GameTooltip', 'CCS_Scanningtooltip', WorldFrame, 'GameTooltipTemplate')\n        local EmptySocket = false\n        local SocketCount = 0;\n        local Enchant = \"\"\n        local ItemUpgradeLevel = \"\"\n        -- Parse Item Tooltip for information that cannot be easily obtained or to cross check for blizzard errors.\n        ItemTip:SetOwner(WorldFrame, 'ANCHOR_NONE');\n        ItemTip:ClearLines()\n        _G[\"CCS_ScanningtooltipTexture1\"]:SetTexture(nil) -- Gem1\n        _G[\"CCS_ScanningtooltipTexture2\"]:SetTexture(nil) -- Gem2\n        _G[\"CCS_ScanningtooltipTexture3\"]:SetTexture(nil) -- Gem3\n        ItemTip:SetHyperlink(link) \n        \n        for m = 1, ItemTip:NumLines() do\n            local enchant = _G[\"CCS_ScanningtooltipTextLeft\"..m]:GetText():match(ENCHANTED_TOOLTIP_LINE:gsub(\"%%s\", \"(.+)\"))\n            local ilvl = _G[\"CCS_ScanningtooltipTextLeft\"..m]:GetText():match(ITEM_LEVEL:gsub('%%d', '(%%d+)'))\n            local pvp_ilvl\n            local emptysocket = _G[\"CCS_ScanningtooltipTextLeft\"..m]:GetText():match(EMPTY_SOCKET_PRISMATIC)\n            local upgradelvl = _G[\"CCS_ScanningtooltipTextLeft\"..m]:GetText():match(ITEM_UPGRADE_TOOLTIP_FORMAT_STRING:gsub(\"%%s %%d/%%d\", \"(%%D+ %%d+/%%d+)\"))\n            \n            if enchant then    Enchant = enchant end\n            if upgradelvl then ItemUpgradeLevel = upgradelvl end\n            if ilvl and (tonumber(ilvl) ~= tonumber(itemiLevel)) then itemiLevel = ilvl    end\n            \n            if c.showpvpilvl then \n                pvp_ilvl = _G[\"CCS_ScanningtooltipTextLeft\"..m]:GetText():match(PVP_ITEM_LEVEL_TOOLTIP:gsub('%%d', '(%%d+)'))\n                if pvp_ilvl and (tonumber(pvp_ilvl) ~= tonumber(itemiLevel)) then itemiLevel = itemiLevel .. \" (\" .. PVP .. \" \" .. pvp_ilvl .. \")\"    end\n            end\n            \n            if emptysocket then \n                EmptySocket = true \n                SocketCount = SocketCount + 1;\n            end\n        end\n        \n        Gemtex1 = _G[\"CCS_ScanningtooltipTexture1\"]:GetTexture()\n        Gemtex2 = _G[\"CCS_ScanningtooltipTexture2\"]:GetTexture()\n        Gemtex3 = _G[\"CCS_ScanningtooltipTexture3\"]:GetTexture()\n        \n        -- Item name info (item name in white as well) [White or Rarity Color, 12]\n        if c.showitemname == true then\n            if c.itemcolorwhite then Color = \"ffffffff\" end\n            if itemName ~= nil then\n                if (string.len(Color) < 8) then Color = \"FF\"..Color end\n                if strlen(itemName) > c.itemnamelength then itemName = format(\"%.\" .. c.itemnamelength .. \"s\", itemName) .. \"...\" end                \n                nameTxt:SetText(\"|c\".. Color .. itemName .. \"|r\") \n            end\n            nameTxt:Show()\n        end\n        \n        -- iLvl information [White] \n        if c.showilvl == true then\n            if c.showitemupgrade then \n                if string.len(ItemUpgradeLevel) > 0 then\n                    local upr, upg, upb, upalpha = c.itemupgradecolor[1], c.itemupgradecolor[2], c.itemupgradecolor[3], c.itemupgradecolor[4];\n                    ItemUpgradeLevel = WrapTextInColor(\"(\" .. ItemUpgradeLevel .. \")\", CreateColor(upr, upg, upb, upalpha))\n                end\n            else\n                ItemUpgradeLevel = \"\"\n            end\n            \n            if leftdisplay and itemiLevel ~= nil then\n                ilvlTxt:SetText(ItemUpgradeLevel .. \" |cFFffffff\" .. itemiLevel .. \"|r\") \n            elseif itemiLevel ~= nil then\n                ilvlTxt:SetText(\"|cFFffffff\" .. itemiLevel .. \" \" .. ItemUpgradeLevel .. \"|r\")\n            end\n            ilvlTxt:Show()\n        end\n        \n        -- Enchant Info [Mint/Red, 10]  (Mint #2afab5)\n        if c.showenchants == true then\n            \n            if Enchant ~= \"\" then Enchant = \"|cFF2afab5\"..Enchant..\"|r\"    end\n            \n            if Enchant == \"\" and c.showenchantgemerrors == true then\n                -- See if an enchant is missing from a slot. Extra code is to allow us to turn on/off the slots each time blizzard makes a change.\n                if slotIndex == 1 then --  \"Head\" -\n                    --Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"                            \n                elseif slotIndex == 2 then --  \"Neck\" !\n                elseif slotIndex == 3 then --  \"Shoulder\"\n                elseif slotIndex == 5 then --  \"Chest\" !\n                    Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"            \n                elseif slotIndex == 6 then --  \"Waist\" -\n                    --Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"            \n                elseif slotIndex == 7 then --  \"Legs\" -\n                    Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"            \n                elseif slotIndex == 8 then --  \"Feet\" !\n                    Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"            \n                elseif slotIndex == 9 then --  \"Wrist\" !\n                    Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"            \n                elseif slotIndex == 10 then --  \"Hands\" !\n                elseif slotIndex == 11 then --  \"Finger0\" !\n                    Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"            \n                elseif slotIndex == 12 then --  \"Finger1\" !\n                    Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"            \n                elseif slotIndex == 15 then --  \"Back\" !\n                    Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"            \n                elseif slotIndex == 16 then --  \"MainHand\" !\n                    Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"            \n                elseif slotIndex == 17 and itemType == \"Weapon\" then --  \"SecondaryHand\" -\n                    Enchant = \"|cFFFF0000<\" .. ENSCRIBE .. \": \" .. ADDON_MISSING .. \">|r\"            \n                end\n            end\n            if strlen(Enchant) > 100 then Enchant = format(\"%.75s\", Enchant) .. \"...\" end\n            enchantTxt:SetText(Enchant)\n            enchantTxt:Show()\n        end\n        \n        -- Display Durability text (white)\n        if c.showdurability == true and durMax ~= nil and durCur ~= nil and durMax > 0 and durCur ~= durMax then\n            local DurPercent = string.format(\"%.f\", durCur/durMax*100)\n            durabilityTxt:SetText(DurPercent..\"%\")\n            durabilityTxt:Show()\n        end\n        \n        if c.showdurabilitybar == true and durMax ~= nil and durCur ~= nil and durMax > 0 and durCur ~= durMax then\n            local DurPercent = durCur/durMax\n            \n            if DurPercent > 0.66 then durbartex:SetColorTexture(0, 1, 0) -- green\n            elseif DurPercent > 0.33 then durbartex:SetColorTexture(1, 1, 0) -- yellow\n            elseif DurPercent > 0.10 then durbartex:SetColorTexture(1, 0, 0) -- red\n            else durbartex:SetColorTexture(1, 0, 0, 0.10) \n            end\n            \n            durbar:SetHeight(30*DurPercent)\n            durbar:Show()\n        end\n        \n        if c.showgems == true then\n            local tooltip, tooltip2, tooltip3 = \"\", \"\", \"\"\n            local _, gem1Link = C_Item.GetItemGem(link, 1)\n            local _, gem2Link = C_Item.GetItemGem(link, 2)\n            local _, gem3Link = C_Item.GetItemGem(link, 3)            \n            local gemCount = 0\n            \n            if Gem1 ~= \"\" or Gemtex1 then gemCount= gemCount+1 end\n            if Gem2 ~= \"\" or Gemtex2 then gemCount= gemCount+1 end\n            if Gem3 ~= \"\" or Gemtex3 then gemCount= gemCount+1 end\n            \n            if slotIndex == 2 and expacID == LE_EXPANSION_DRAGONFLIGHT then\n                gemCount = 3\n            end\n            \n            if gemCount == 1 then\n                gemIconframe1:ClearAllPoints()\n                gemIconframe1:SetPoint(SubElementSetPoint2, slotFrameName, SubElementSetPoint, -8 * neg, 0)\n            elseif gemCount == 2 then\n                gemIconframe1:ClearAllPoints()\n                gemIconframe2:ClearAllPoints()\n                gemIconframe1:SetPoint(\"TOP\"..SubElementSetPoint2, slotFrameName, \"TOP\"..SubElementSetPoint, -8 * neg, -2)\n                gemIconframe2:SetPoint(\"BOTTOM\"..SubElementSetPoint2, slotFrameName, \"BOTTOM\"..SubElementSetPoint, -8 * neg, 2)\n            elseif gemCount == 3 then\n                gemIconframe1:ClearAllPoints()\n                gemIconframe2:ClearAllPoints()\n                gemIconframe3:ClearAllPoints()\n                gemIconframe2:ClearAllPoints()\n                gemIconframe1:SetPoint(\"TOP\"..SubElementSetPoint2, slotFrameName, \"TOP\"..SubElementSetPoint, -8 * neg, 4)\n                gemIconframe2:SetPoint(SubElementSetPoint2, slotFrameName, SubElementSetPoint, -8 * neg, 0)\n                gemIconframe3:SetPoint(\"BOTTOM\"..SubElementSetPoint2, slotFrameName, \"BOTTOM\"..SubElementSetPoint, -8 * neg, -4)\n            end\n            \n            local Gem1type, Gem2type, Gem3type = 0,0,0\n            \n            if Gem1 ~= \"\" then\n                local icon = C_Item.GetItemIconByID(Gem1)\n                gemIconframe1:SetNormalTexture(icon)\n                gemIconframe1:Show()\n            elseif Gemtex1 then\n                gemIconframe1:SetNormalTexture(Gemtex1)\n                if aura_env.GemInfo[Gemtex1] then tooltip = aura_env.GemInfo[Gemtex1].text else tooltip = EMPTY_SOCKET_TINKER end\n                gemIconframe1:Show()\n            elseif slotIndex == 2 and expacID == LE_EXPANSION_DRAGONFLIGHT and c.showenchants then\n                gemIconframe1:SetNormalTexture(\"Interface\\\\COMMON\\\\Indicator-Red.blp\")\n                tooltip = EMPTY_SOCKET_PRISMATIC .. \": \" .. ADDON_MISSING\n                gemIconframe1:Show()\n            end\n            \n            if Gem2 ~= \"\" then\n                local icon = C_Item.GetItemIconByID(Gem2)\n                gemIconframe2:SetNormalTexture(icon)\n                gemIconframe2:Show()\n            elseif Gemtex2 then\n                gemIconframe2:SetNormalTexture(Gemtex2)\n                if aura_env.GemInfo[Gemtex2] then tooltip2 = aura_env.GemInfo[Gemtex2].text else tooltip2 = EMPTY_SOCKET_TINKER end\n                gemIconframe2:Show()\n            elseif slotIndex == 2 and expacID == LE_EXPANSION_DRAGONFLIGHT and c.showenchants then\n                gemIconframe2:SetNormalTexture(\"Interface\\\\COMMON\\\\Indicator-Red.blp\")\n                tooltip2 = EMPTY_SOCKET_PRISMATIC .. \": \" .. ADDON_MISSING\n                gemIconframe2:Show()\n            end\n            \n            if Gem3 ~= \"\" then\n                local icon = C_Item.GetItemIconByID(Gem3)\n                gemIconframe3:SetNormalTexture(icon)\n                gemIconframe3:Show()\n            elseif Gemtex3 then\n                gemIconframe3:SetNormalTexture(Gemtex3)\n                if aura_env.GemInfo[Gemtex3] then tooltip3 = aura_env.GemInfo[Gemtex3].text else tooltip3 = EMPTY_SOCKET_TINKER end\n                gemIconframe3:Show()\n            elseif slotIndex == 2 and expacID == LE_EXPANSION_DRAGONFLIGHT and c.showenchants then\n                gemIconframe3:SetNormalTexture(\"Interface\\\\COMMON\\\\Indicator-Red.blp\")\n                tooltip3 = EMPTY_SOCKET_PRISMATIC .. \": \" .. ADDON_MISSING\n                gemIconframe3:Show()\n            end\n            \n            gemIconframe1:SetScript(\"OnEnter\", function() GameTooltip:SetOwner(UIParent, \"ANCHOR_CURSOR\")\n                    if gem1Link then\n                        GameTooltip:SetHyperlink(gem1Link)\n                    else\n                        GameTooltip:AddDoubleLine(tooltip, \"\", 1, 1, 1, 1, 1, 1) \n                    end\n                    GameTooltip:Show()\n            end)\n            gemIconframe1:SetScript(\"OnLeave\", function() GameTooltip:Hide() end)\n            gemIconframe2:SetScript(\"OnEnter\", function() GameTooltip:SetOwner(UIParent, \"ANCHOR_CURSOR\")\n                    if gem2Link then\n                        GameTooltip:SetHyperlink(gem2Link)\n                    else\n                        GameTooltip:AddDoubleLine(tooltip2, \"\", 1, 1, 1, 1, 1, 1) \n                    end\n                    GameTooltip:Show()\n            end)\n            gemIconframe2:SetScript(\"OnLeave\", function() GameTooltip:Hide() end)\n            gemIconframe2:SetScript(\"OnClick\", function()  end)\n            \n            gemIconframe3:SetScript(\"OnEnter\", function() GameTooltip:SetOwner(UIParent, \"ANCHOR_CURSOR\")\n                    if gem3Link then\n                        GameTooltip:SetHyperlink(gem3Link)\n                    else\n                        GameTooltip:AddDoubleLine(tooltip3, \"\", 1, 1, 1, 1, 1, 1) \n                    end\n                    GameTooltip:Show()\n            end)\n            gemIconframe3:SetScript(\"OnLeave\", function() GameTooltip:Hide() end)\n            gemIconframe3:SetScript(\"OnClick\", function()  end)            \n        end\n        \n        if c.showitemcolor then\n            local setr, setg, setb, setalpha = c.setitemcolor[1], c.setitemcolor[2], c.setitemcolor[3], c.setitemcolor[4];\n            \n            if leftdisplay then \n                bgfadertex:SetTexCoord(1,0,0,1)\n                \n                if itemRarity == 1 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(.5, .5, .5, .2), CreateColor(1, 1, 1, .6))  -- white (Common)\n                elseif itemRarity == 2 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(.06, .5, 0, .2), CreateColor(0.12, 1, 0, .6))  -- green (Uncommon)\n                elseif itemRarity == 3 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(0, .22, .435, .2), CreateColor(0, 0.44, 0.87, .6)) -- Blue (Rare)\n                elseif itemRarity == 4 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(.32, .105, .465, .2), CreateColor(0.64, 0.21, 0.93, .6)) -- Purple (Epic)\n                elseif itemRarity == 5 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(.5, .25, 0, .2), CreateColor(1, 0.5, 0, .6)) -- Orange (Legendary)\n                elseif itemRarity == 6 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(.45, .4, .25, .2), CreateColor(0.9, 0.8, 0.5, .6)) -- Tan (Artifact)\n                elseif itemRarity == 7 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(0, .4, .5, .2), CreateColor(0, 0.8, 1, .6)) -- Light Blue (Heirloom)   \n                else bgfadertex:SetGradient(\"Horizontal\", CreateColor(.31, .31, .31, .2), CreateColor(0.62, 0.62, 0.62, .6)) -- gray / poor    \n                end\n                \n                if c.showsetitems and setID then \n                    if c.showsetclasscolor then\n                        setr, setg, setb = GetClassColor(select(2, UnitClass(\"player\")))\n                        setalpha = .8\n                    end\n                    bgfadertex:SetGradient(\"Horizontal\", CreateColor(setr/2, setg/2, setb/2, .2), CreateColor(setr, setg, setb, setalpha)) -- Set Item Color Left Display\n                end\n                \n            else\n                if itemRarity == 1 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(1, 1, 1, .6), CreateColor(.5, .5, .5, .2))  -- white (Common)\n                elseif itemRarity == 2 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(0.12, 1, 0, .6), CreateColor(.06, .5, 0, .2))  -- green (Uncommon)\n                elseif itemRarity == 3 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(0, 0.44, 0.87, .6), CreateColor(0, .22, .435, .2)) -- Blue (Rare)\n                elseif itemRarity == 4 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(0.64, 0.21, 0.93, .6), CreateColor(.32, .105, .465, .2)) -- Purple (Epic)\n                elseif itemRarity == 5 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(1, 0.5, 0, .6), CreateColor(.5, .25, 0, .2)) -- Orange (Legendary)\n                elseif itemRarity == 6 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(0.9, 0.8, 0.5, .6), CreateColor(.45, .4, .25, .2)) -- Tan (Artifact)\n                elseif itemRarity == 7 then bgfadertex:SetGradient(\"Horizontal\", CreateColor(0, 0.8, 1, .6), CreateColor(0, .4, .5, .2)) -- Light Blue (Heirloom)   \n                else bgfadertex:SetGradient(\"Horizontal\", CreateColor(0.62, 0.62, 0.62, .6), CreateColor(0.62, 0.62, 0.62, .6)) -- gray / poor    \n                end\n                \n                if c.showsetitems and setID then \n                    if c.showsetclasscolor then\n                        setr, setg, setb = GetClassColor(select(2, UnitClass(\"player\")))\n                        setalpha = .8\n                    end\n                    bgfadertex:SetGradient(\"Horizontal\", CreateColor(setr, setg, setb, setalpha), CreateColor(0, 0, 0, .2)) -- Set Item Color Right Display\n                end\n            end\n            bgfader:Show()\n        end \n    end\n    \nend\n\naura_env.loopitems = function()\n    for slotIndex = 1,19 do \n        aura_env.updateLocationInfo(slotIndex)\n    end \nend\n\n\n\n\n\n\n\n",
