["animate"] = true,
["customGrow"] = "function(newPositions, activeRegions)\n    -- First apply our style settings if available\n    if QuaziiWA and QuaziiWA.UpdateBuffIcons then\n        QuaziiWA:UpdateBuffIcons(newPositions, activeRegions)\n    else\n        -- Fallback if the central function isn't loaded yet\n        -- Error message removed to prevent spam on first import\n    end\n    \n    -- Get configuration values\n    local iconWidth = 30     -- Default if config not available\n    local spacing = 2        -- Default spacing between icons\n    \n    if QuaziiWA and QuaziiWA.GetBuffConfig then\n        local cfg = QuaziiWA:GetBuffConfig()\n        iconWidth = cfg.buffIconWidth or iconWidth\n        spacing = cfg.buffIconSpacing or spacing\n    end\n    \n    -- Calculate the total width needed\n    local totalIcons = #activeRegions\n    local totalWidth = (totalIcons * iconWidth) + ((totalIcons - 1) * spacing)\n    \n    -- Calculate starting position to center the icons\n    local startX = -totalWidth / 2\n    \n    -- Position the icons centered horizontally\n    local xPos = startX\n    \n    for i, regionData in ipairs(activeRegions) do\n        if regionData and regionData.region then\n            -- Center each icon on its position point (add half icon width)\n            newPositions[i] = {xPos + (iconWidth / 2), 0}\n            \n            -- Move to next position\n            xPos = xPos + iconWidth + spacing\n            \n            -- Show the region\n            regionData.region:Show()\n        end\n    end\nend",
