["custom"] = "function(allstates, event, arg1, arg2)\n    local aura_env = aura_env\n    local throttle = 0\n    local throttlecheck\n    \n    if InspectFrame == nil or InspectFrame.unit == nil or InCombatLockdown() then return end\n    \n    if (InspectFrame.throttle) then\n        throttle = InspectFrame.throttle\n    end\n    \n    throttlecheck = GetTime() - throttle\n    \n    if throttlecheck >= 1 then -- throttle to 1 update every 1s (at most).\n        \n        aura_env.initializeinspectframe()\n        aura_env.loopitems()\n        \n    end\n    \n    InspectFrame.throttle = GetTime()\n    \n    return true\n    \nend",
