["custom_hide"] = "timed",
["customVariables"] = "{\n    wcStacks = \"number\",\n    fofStacks = \"number\",\n    isImmune = \"bool\",\n    textImmune = \"string\",    \n    flurryFlying = \"bool\",\n    hasWC = \"bool\",\n    hasFoF = \"bool\",\n    expirationTime = true,\n    duration = true,\n}",
["event"] = "Health",
["subeventPrefix"] = "SPELL",
["unit"] = "player",
["custom"] = "function(allstates, event, ...)\n    \n    if event == \"THV_SWC_Update\" then\n        aura_env.is_active, aura_env.wc_stacks, aura_env.wc_expirationTime, aura_env.wc_duration, aura_env.fof_stacks, aura_env.is_immune, aura_env.string_immune, aura_env.flurry_flying = ...\n        \n        allstates:Update(\"\", aura_env.GetState() )\n        \n    elseif  event == \"OPTIONS\" then\n        aura_env.Preview_SetState()\n        allstates:Update(\"\", aura_env.GetState() )\n        aura_env.Preview_SetVisuals()\n        \n    elseif event == \"STATUS\" then\n        WeakAuras.ScanEvents(\"THV_SWC_RequestStatus\")\n        \n    end\n    \n    return true\nend",
