["actions"] = {
["start"] = {
},
["init"] = {
["custom"] = "-----------------------------------------------\n-- variables and tables\n-----------------------------------------------\naura_env.is_active = false\naura_env.is_immune = false\naura_env.wc_stacks = 0\naura_env.fof_stacks = 0\naura_env.wc_expirationTime = 0\naura_env.wc_duration = 8\naura_env.string_immune = \"\"\naura_env.flurry_flying = false\n\nif aura_env.config.always_show then\n    aura_env.GetState = function()\n        return {\n            progressType = aura_env.is_active and \"timed\" or \"static\",\n            duration = aura_env.wc_duration,\n            expirationTime = aura_env.wc_expirationTime,\n            autoHide = false,\n            flurryFlying = aura_env.flurry_flying,\n            wcStacks = aura_env.wc_stacks,\n            hasWC = aura_env.is_active,\n            fofStacks = aura_env.fof_stacks,\n            hasFoF = aura_env.fof_stacks > 0,\n            isImmune = aura_env.is_immune,\n            textImmune = aura_env.string_immune,\n            show = true,\n            changed = true,\n        } \n    end\n    \nelse\n    aura_env.GetState = function()\n        return {\n            progressType = \"timed\",\n            duration = aura_env.wc_duration,\n            expirationTime = aura_env.wc_expirationTime,\n            autoHide = true,\n            flurryFlying = aura_env.flurry_flying,\n            wcStacks = aura_env.wc_stacks,\n            hasWC = aura_env.is_active,\n            fofStacks = aura_env.fof_stacks,\n            hasFoF = aura_env.fof_stacks > 0,\n            isImmune = aura_env.is_immune,\n            textImmune = aura_env.string_immune,\n            show = aura_env.is_active,\n            changed = true,\n        } \n    end\nend\n\n-- preview helpers\naura_env.Preview_SetState = function()\n    local lookup_immune = {\n        [1] = false,\n        [2] = \"Immune\",\n        [3] = \"Evade\",\n    }\n    aura_env.is_immune = lookup_immune[aura_env.config.preview_immunity] and true or false\n    aura_env.string_immune = lookup_immune[aura_env.config.preview_immunity]\n    aura_env.wc_stacks = aura_env.config.preview_wc\n    aura_env.fof_stacks = aura_env.config.preview_fof\n    aura_env.wc_expirationTime = GetTime() + 8\n    aura_env.is_active = aura_env.wc_stacks > 0\n    aura_env.flurry_flying = aura_env.config.preview_flurry\n    \nend\n\naura_env.Preview_SetVisuals = function()\n    \n    if aura_env.config.preview_ooc then\n        aura_env.region:SetRegionAlpha(aura_env.config.alpha_ooc)\n    else\n        aura_env.region:SetRegionAlpha(1)\n    end\n    \n    if not aura_env.config.always_show and not aura_env.is_active then\n        aura_env.region:SetRegionAlpha(0)\n    end\n    \nend",
["do_custom"] = true,
},
