},
["init"] = {
["custom"] = "if not aura_env.region._mouseoverFrame then\n    aura_env.region._mouseoverFrame = CreateFrame(\"FRAME\", nil, WeakAurasFrame)\nend\nlocal frame = aura_env.region._mouseoverFrame\nframe:SetAllPoints(aura_env.region)\nframe:SetScript(\"OnEnter\", function() WeakAuras.ScanEvents(\"_mouseoverFrame_event\", true) end)\nframe:SetScript(\"OnLeave\", function() WeakAuras.ScanEvents(\"_mouseoverFrame_event\", false) end)\nframe:SetMouseClickEnabled(false)\n",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["type"] = "custom",
["subeventSuffix"] = "_CAST_START",
["names"] = {
},
["event"] = "Chat Message",
["unit"] = "player",
["spellIds"] = {
},
["customName"] = "function()\n    \n    local sumCurrent = 0\n    local sumMaximum = 0\n    \n    for i = 1,18,1\n    do\n        local current, maximum = GetInventoryItemDurability(i)\n        if current ~= nil then sumCurrent = sumCurrent + current end\n        if maximum ~= nil then sumMaximum = sumMaximum + maximum end\n        \n    end\n    \n    local avgDurability = (sumCurrent / sumMaximum) * 100\n    \n    \n    \n    local r=floor(avgDurability);\n    if r<=25 then\n        r='|cffff0000'..r..'%'..'|r';\n    elseif r<=75 then\n        r='|cffffff00'..r..'%'..'|r';\n    elseif r>75 then\n        r='|cff00ff00'..r..'%'..'|r';\n    end\n    \n    return r\n    \nend",
["custom"] = "function()\n    return true              \nend\n\n\n\n\n",
["custom_type"] = "status",
["check"] = "event",
["events"] = "UPDATE_INVENTORY_DURABILITY,PLAYER_ENTERING_WORLD",
