["cooldownSwipe"] = true,
["customTextUpdate"] = "event",
["url"] = "quazii.com",
["icon"] = true,
["triggers"] = {
{
["trigger"] = {
["spellId"] = {
"316958",
},
["duration"] = "30",
["names"] = {
},
["use_sourceFlags"] = true,
["use_cloneId"] = true,
["debuffType"] = "HELPFUL",
["type"] = "custom",
["use_destNpcId"] = false,
["custom_type"] = "stateupdate",
["sourceFlags"] = "InGroup",
["unit"] = "player",
["event"] = "Combat Log",
["custom"] = "function(a, event, ...)\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subEvent, _, sourceGUID, sourceName, _, _, destGUID, _, _, _, spellID, _, _, casterGUID, casterName, _, _, _, absorbSpellName, _, amount, _ = ...\n        \n        if subEvent == \"SPELL_CAST_SUCCESS\" then\n            --cast\n            if spellID == 51052 then\n                local sourceUnit\n                for unit in WA_IterateGroupMembers() do\n                    if UnitGUID(unit) == sourceGUID then\n                        sourceUnit = unit\n                    end\n                end\n                if not sourceUnit then return end\n                -- TODO conduit duration\n                local dur = 8\n                a[sourceGUID] = {\n                    show = true,\n                    changed = true,\n                    unitCaster = sourceUnit,\n                    progressType = \"timed\",\n                    duration = dur,\n                    expirationTime = GetTime() + dur,\n                    autoHide = true,\n                    ticker = C_Timer.NewTicker(aura_env.tick, function() WeakAuras.ScanEvents(\"AMZ_UPDATE\", sourceGUID) end, dur / aura_env.tick),\n                }\n                \n                return true\n            end\n        elseif subEvent == \"SPELL_AURA_APPLIED\" then\n            -- wrong event fix\n            if spellID == 145629 then \n                local value = casterName\n                for _,v in pairs(a) do \n                    if not v.value then \n                        v.value = value\n                        v.changed = true\n                        return\n                    end\n                end\n                return true\n            end\n            --[[elseif subEvent == \"UNIT_DIED\" then \n        --owner died\n        if not destGUID or not allstates[destGUID] then return end\n        if allstates[destGUID].timer then allstates[destGUID].timer:Cancel() end\n        allstates[destGUID].show = false\n        allstates[destGUID].changed = true\n        return true]]\n        elseif subEvent == \"SPELL_ABSORBED\" then \n            if absorbSpellName ~= aura_env.amz then return end\n            if not a[casterGUID] then return end\n            a[casterGUID].value = a[casterGUID].value - amount \n        end\n        \n    elseif event == \"AMZ_UPDATE\" then\n        local guid = ...\n        if not guid then return end \n        if not a[guid] then return end\n        if a[guid].value and a[guid].value < 10000 then \n            a[guid].show = false\n        end\n        a[guid].changed = true\n        return true\n    end\nend\n\n\n",
["events"] = "CLEU:SPELL_CAST_SUCCESS:SPELL_ABSORBED:SPELL_AURA_APPLIED:UNIT_DIED,AMZ_UPDATE",
