["custom"] = "--handles deciding whether or not you have the 11.2 tier set. Only called on equipment changes and loading into the game.\n\nfunction(...)\n    local set_bonus_count = 0\n    \n    for slot_id, tier_id in pairs(aura_env.augur_tier_slots) do\n        local item_id = GetInventoryItemID(\"player\", slot_id)\n        if item_id ~= nil and item_id == tier_id then\n            set_bonus_count = set_bonus_count + 1\n        end\n    end\n    \n    if set_bonus_count >= 4 then\n        aura_env.has_augur_set_bonus = true\n    else\n        aura_env.has_augur_set_bonus = false\n    end\n    \n    aura_env:debug(\"Changed tier set bonus active to \" .. tostring(aura_env.has_augur_set_bonus))\n    \n    return true\n    \nend",
