["custom"] = "--handles incrementing BLP\n--BLP Stack Counter is used from this trigger\n\nfunction(...)\n    local event, _, subevent, _, source_guid, _, _, _, _, _, _, _, spell_id = ...    \n    if source_guid == aura_env.playerGUID or event == \"BLP_INIT\" then     \n        local count = aura_env.blp_count\n        if aura_env:has_intuition() then\n            aura_env:blp_increment_debug(\"Player has intuition BLP will not increment.\")\n            return true\n        end\n        \n        if subevent == \"SPELL_CAST_SUCCESS\" then\n            local success_spell = false\n            for _, value in ipairs(aura_env.cast_success_spells) do\n                if value == spell_id then\n                    success_spell = true\n                end\n            end\n            \n            if success_spell then\n                aura_env.blp_count = aura_env.blp_count + 1\n                aura_env:blp_increment_debug(\"Incrementing BLP for valid successful spell cast. \" .. spell_id)\n            end\n        elseif event == \"BLP_ECHOED_ARCANE_EXPLOSION\" then\n            aura_env.blp_count = aura_env.blp_count + 1\n            aura_env:blp_increment_debug(\"Incrementing BLP for echoed arcane explosion\")\n        elseif event == \"BLP_ORB_BARRAGE\" then\n            aura_env.blp_count = aura_env.blp_count + 1\n            aura_env:blp_increment_debug(\"Incrementing BLP for orb barrage\")\n        elseif event == \"BLP_ENERGY_RECONSTITUTION\" then\n            aura_env.blp_count = aura_env.blp_count + 1\n            aura_env:blp_increment_debug(\"Incrementing BLP for energy reconstitution\")\n        end\n        \n        if count ~= aura_env.blp_count or event == \"BLP_INTUITION_AURA_REMOVED\" or event == \"BLP_INTUITION_RESET\" or event == \"BLP_INTUITION_AURA_APPLIED\" then\n            local stacks = 11 - aura_env.blp_count\n            aura_env:post_external_event(\"BLP_INTUITION_UPDATE_EXTERNAL\", source_guid, stacks, 0)\n        end\n        \n        \n        \n        return true\n    end\nend",
