["use_spellName"] = true,
["custom"] = "--handles resetting at the start of Raid bosses and M+ dungeons\n\nfunction(...)\n    local event = ...    \n    \n    if event == \"ENCOUNTER_START\" then\n        local _, _, _, difficulty_id = ...\n        if difficulty_id then\n            local _, group_type, _, _ = GetDifficultyInfo(difficulty_id)\n            if group_type == \"raid\" then\n                aura_env:post_event(\"BLP_INTUITION_RESET\", UnitGUID(\"player\"), 0)\n                aura_env.blp_count = 0\n                return true\n            end\n        end\n    elseif event == \"CHALLENGE_MODE_START\" then\n        aura_env:post_event(\"BLP_INTUITION_RESET\", UnitGUID(\"player\"), 0)\n        aura_env.blp_count = 0\n        return true\n    end \n    \nend",
