["customStacks"] = "\n\n\n\n",
["customDuration"] = "",
["use_spellName"] = true,
["custom"] = "--handles resetting the BLP when you use intuition (and protection against this with harmony intuitions)\n\nfunction(...)\n    local _, _, subevent, _, source_guid, _, _, _, _, _, _, _, spell_id = ...\n    \n    if source_guid == aura_env.playerGUID then  \n        if subevent == \"SPELL_AURA_APPLIED\" and spell_id == aura_env.intuition then\n            if aura_env:is_eligible_for_harmony_intuition() and aura_env.is_harmony_intuition ~= true and aura_env:get_harmony_stacks() == aura_env.max_hamony_stack then\n                aura_env:intuition_reset_debug(\"Harmony Intuition applied. BLP will not reset on removal.\")\n                aura_env.is_harmony_intuition = true\n            else\n                aura_env:intuition_reset_debug(\"Intuition applied. BLP will reset on removal.\")\n                aura_env.is_harmony_intuition = false\n            end\n            aura_env:post_event(\"BLP_INTUITION_AURA_APPLIED\", source_guid, 0)\n        end\n        \n        if subevent == \"SPELL_AURA_REMOVED\" and spell_id == aura_env.intuition then\n            if aura_env.is_harmony_intuition ~= true then\n                aura_env.is_harmony_intuition = false\n                aura_env:intuition_reset_debug(\"Intuition removed. BLP reset.\")\n                aura_env.blp_count = 0\n            else\n                aura_env.is_harmony_intuition = false\n                aura_env:intuition_reset_debug(\"Harmony Intution removed. BLP not reset.\")\n            end\n            aura_env:post_event(\"BLP_INTUITION_AURA_REMOVED\", source_guid, 0)\n        end\n        return true\n    end\nend\n\n\n\n\n",
