["customDuration"] = "",
["use_spellName"] = true,
["custom"] = "--handles updating variables the incrementer is dependent on\nfunction(...)\n    local _, timestamp, subevent, _, source_guid, _, _, _, _, _, _, _, spell_id = ...\n    \n    if source_guid == aura_env.playerGUID then    \n        if subevent == \"SPELL_CAST_SUCCESS\" then\n            aura_env:handle_echo_arcane_explosion_event(spell_id, source_guid)\n            aura_env:handle_orb_barrage_event(spell_id, timestamp, source_guid)\n        elseif subevent == \"SPELL_DAMAGE\" then\n            aura_env:handle_energy_reconsitution(spell_id, timestamp, source_guid) \n        elseif subevent == \"SPELL_AURA_APPLIED\" or subevent == \"SPELL_AURA_APPLIED_DOSE\" then\n            --adds clearcasting flag when the aura is added. used for arcane explosion's echo\n            if spell_id == aura_env.clearcasting then\n                aura_env:blp_increment_debug(\"Setting clearcasting to true for future arcane explosion echos.\")\n                aura_env.has_clearcasting = true\n            end\n        elseif subevent == \"SPELL_AURA_REMOVED\" then\n            --removes clearcasting flag when the aura is removed completely. used for arcane explosion's echo\n            if spell_id == aura_env.clearcasting then\n                aura_env:blp_increment_debug(\"Setting clearcasting to false for future arcane explosion echos.\")\n                aura_env.has_clearcasting = false\n            end\n        elseif subevent == \"SPELL_ENERGIZE\" then\n            --store timestamp for last arcane orb energized\n            if spell_id == aura_env.arcane_orb then\n                aura_env:blp_increment_debug(\"Setting Orb Barrage Last Timestamp to \" .. timestamp)\n                aura_env.orb_barrage_timestamp = timestamp \n            end\n        end\n        return true\n    end\nend",
