["init"] = {
["custom"] = "function aura_env:init_blp_variables() \n    --init variables\n    aura_env.playerGUID = UnitGUID(\"player\")\n    aura_env.blp_count = 0\n    aura_env.is_harmony_intuition = false\n    aura_env.max_hamony_stack = 20\n    local _, _, harmony_stacks =  WA_GetUnitBuff(\"player\", aura_env.arcane_harmony)\n    if harmony_stacks then\n        aura_env.last_harmony_stacks = harmony_stacks\n    else\n        aura_env.last_harmony_stacks = 0\n    end\n    \n    aura_env.intuition_debug_flag = self.config.intuition_debug\n    aura_env.blp_increment_debug_flag = self.config.blp_increment_debug\n    aura_env.debug_all_flag = self.config.debug_all\n    if aura_env.intuition_debug_flag == nil then\n        aura_env.intuition_debug_flag = false\n    end\n    if aura_env.blp_increment_debug_flag == nil then\n        aura_env.blp_increment_debug_flag = false\n    end\n    if aura_env.debug_all_flag == nil then\n        aura_env.debug_all_flag = false\n    elseif aura_env.debug_all_flag == true then\n        aura_env.blp_increment_debug_flag = true\n        aura_env.intuition_debug_flag = true\n    end\n    \n    local clearcasting =  WA_GetUnitBuff(\"player\", aura_env.clearcasting)\n    if clearcasting then\n        aura_env.has_clearcasting = true\n    else\n        aura_env.has_clearcasting = false\n    end\n    \n    aura_env.has_augur_set_bonus = false\n    --11.2 Tier Set Items\n    aura_env.augur_head = 237718\n    aura_env.augur_shoulder = 237716\n    aura_env.augur_chest = 237721\n    aura_env.augur_legs = 237717\n    aura_env.augur_hands = 237719\n    \n    --tier set slot map\n    aura_env.augur_tier_slots = {\n        [INVSLOT_SHOULDER] = aura_env.augur_shoulder,\n        [INVSLOT_HAND] = aura_env.augur_hands,\n        [INVSLOT_LEGS] = aura_env.augur_legs,\n        [INVSLOT_CHEST] = aura_env.augur_chest,\n        [INVSLOT_HEAD] = aura_env.augur_head\n    }\n    \n    --spell id constants\n    aura_env.arcane_blast = 30451\n    aura_env.arcane_explosion = 1449\n    aura_env.arcane_missiles = 5143\n    aura_env.arcane_barrage = 44425\n    aura_env.arcane_orb = 153626\n    aura_env.touch_of_the_magi = 321507\n    aura_env.intuition = 1223797\n    aura_env.arcane_harmony = 384455\n    aura_env.clearcasting = 263725\n    aura_env.arcane_explosion_er = 461508\n    \n    --SPELL_CAST_SUCCESS table\n    aura_env.cast_success_spells = {\n        aura_env.arcane_blast,\n        aura_env.arcane_explosion,\n        aura_env.arcane_missiles,\n        aura_env.arcane_barrage,\n        aura_env.arcane_orb,\n        aura_env.touch_of_the_magi\n    } \n    \n    WeakAuras.ScanEvents(\"BLP_INIT\")\nend\n\n--helper functions\nfunction aura_env:get_harmony_stacks()\n    local _, _, harmony_stacks =  WA_GetUnitBuff(\"player\", aura_env.arcane_harmony)\n    if harmony_stacks ~= nil then\n        return harmony_stacks\n    end\n    \n    return 0\nend\n\nfunction aura_env:has_intuition()\n    local intuition =  WA_GetUnitBuff(\"player\", aura_env.intuition)\n    if intuition then\n        return true\n    end\n    \n    return false\nend\n\nfunction aura_env:is_eligible_for_harmony_intuition()\n    local hero_spec_id = C_ClassTalents.GetActiveHeroTalentSpec()\n    local spellslinger = false\n    if hero_spec_id and hero_spec_id == 40 then\n        spellslinger = true\n    end\n    \n    aura_env:intuition_reset_debug(\"Harmony Intuition eligibility is \" .. tostring(spellslinger and aura_env.has_augur_set_bonus))\n    return spellslinger and aura_env.has_augur_set_bonus\nend\n\nfunction aura_env:handle_echo_arcane_explosion_event(spell_id, source_guid)\n    if spell_id == aura_env.arcane_explosion then\n        aura_env:blp_increment_debug(\"Checking for echoed arcane explosion... \" .. tostring(aura_env.has_clearcasting))\n        if aura_env.has_clearcasting then\n            aura_env:post_event(\"BLP_ECHOED_ARCANE_EXPLOSION\", source_guid, .4)\n        end    \n    end\nend\n\nfunction aura_env:handle_orb_barrage_event(spell_id, timestamp, source_guid)\n    if spell_id == aura_env.arcane_barrage and aura_env.orb_barrage_timestamp then        \n        local difference = timestamp - aura_env.orb_barrage_timestamp\n        aura_env:blp_increment_debug(\"Checking difference in current timestamp of arcane barrage and last timestamp from orb barrage. Difference is \" .. difference .. \"s\")\n        if difference <= 0.1 then\n            aura_env:post_event(\"BLP_ORB_BARRAGE\", source_guid, .2)\n        end\n    end\nend \n\nfunction aura_env:handle_energy_reconsitution(spell_id, timestamp, source_guid) \n    --specific implementation for Energy Reconstitution because this event will trigger duplicates if it hits multiple targets, but the BLP is only increased once.\n    if spell_id == aura_env.arcane_explosion_er and aura_env.er_ae_last_timestamp ~= timestamp then\n        aura_env.er_ae_last_timestamp = timestamp\n        aura_env:post_event(\"BLP_ENERGY_RECONSTITUTION\", source_guid, 0)\n    end\nend\n\nfunction aura_env:post_event(eventName, source_guid, tick)\n    if aura_env:has_intuition() ~= true then\n        aura_env:blp_increment_debug(\"Posting event: \" .. eventName)\n        C_Timer.After(tick, function()\n                WeakAuras.ScanEvents(eventName, nil, nil, nil, source_guid)\n        end)\n    else\n        aura_env:blp_increment_debug(\"Player has intuition, not posting event: \" .. eventName)\n    end\n    \nend\n\nfunction aura_env:post_external_event(eventName, source_guid, countdown, tick)\n    aura_env:blp_increment_debug(\"Posting event: \" .. eventName)\n    C_Timer.After(tick, function()\n            WeakAuras.ScanEvents(eventName, source_guid, countdown)\n    end)\nend\n\n--debug functions\nfunction aura_env:log(message)\n    print(message)\nend\n\nfunction aura_env:debug(message)\n    if aura_env.debug_all_flag then\n        aura_env:log(message)\n    end\nend\n\nfunction aura_env:intuition_reset_debug(message)\n    if aura_env.intuition_debug_flag then\n        aura_env:log(message)\n    end \nend\n\nfunction aura_env:blp_increment_debug(message)\n    if aura_env.blp_increment_debug_flag then\n        local stacks = 11 - aura_env.blp_count\n        message = message .. \" count = \" .. stacks\n        aura_env:log(message)\n    end \nend\n\naura_env:init_blp_variables()",
["do_custom"] = true,
},
