["customText"] = "function()\n    if WeakAuras.IsOptionsOpen() and METHODAPI then\n        if not aura_env.last or not aura_env.last[aura_env.region] or aura_env.last[aura_env.region] < GetTime() - 1 then\n            aura_env.last = aura_env.last or {}\n            aura_env.last[aura_env.region] = GetTime()\n            METHODAPI.UpdateIconAura(aura_env.region, \"Method Externals Icon Dummy\")\n        end\n    end\nend",
