["init"] = {
["custom"] = "-- SOURCES: WoWHead.com Guides.\n\n-- Death Knight.  Riders of the Apocalypse (rota), Deathbringer (db), San'layn (sl)\naura_env.suitwwpvestats_dk_frost_rota = \"ILVL>MAST>CRIT>HASTE>VERS\"\naura_env.suitwwpvestats_dk_frost_db = \"ILVL>MAST>CRIT>HASTE>VERS\"\naura_env.suitwwpvestats_dk_unholy_sl = \"ILVL>HASTE>MAST>CRIT>VERS\"\naura_env.suitwwpvestats_dk_unholy_rota = \"ILVL>HASTE>MAST>CRIT>VERS\"\naura_env.suitwwpvestats_dk_blood_sl = \"ILVL>HASTE>MAST=CRIT=VERS\"\naura_env.suitwwpvestats_dk_blood_db = \"ILVL>MAST=CRIT=VERS>HASTE\"\n\n-- Demon Hunter.  Fel-scarred (fs), Aldrachi Reaver (ar)\naura_env.suitwwpvestats_dh_havoc_fs = \"CRIT>MAST>HASTE>VERS>ILVL\"\naura_env.suitwwpvestats_dh_havoc_ar = \"CRIT>MAST>HASTE>VERS>ILVL\"\naura_env.suitwwpvestats_dh_vengeance_fs = \"ILVL>HASTE>CRIT>VERS>MAST\"\naura_env.suitwwpvestats_dh_vengeance_ar = \"ILVL>HASTE>CRIT>VERS>MAST\"\n--aura_env.suitwwpvestats_dh_devourer_fs = \"ILVL>HASTE>CRIT>VERS>MAST\"  COMING SOON\n--aura_env.suitwwpvestats_dh_devourer_ar = \"ILVL>HASTE>CRIT>VERS>MAST\"  COMING SOON\n\n-- Druid.  Keeper of the Grove (kotg), Elune's Chosen (ec), Druid of the Claw (dotc), Wildstalker (ws)\naura_env.suitwwpvestats_druid_balance_kotg = \"ILVL>MAST>CRIT>VERS>HASTE\"\naura_env.suitwwpvestats_druid_balance_ec = \"ILVL>MAST>HASTE>CRIT>VERS\"\naura_env.suitwwpvestats_druid_feral_dotc = \"ILVL>MAST>CRIT>HASTE>VERS\"\naura_env.suitwwpvestats_druid_feral_ws = \"ILVL>MAST>CRIT>HASTE>VERS\"\naura_env.suitwwpvestats_druid_guardian_dotc = \"ILVL>HASTE>VERS>MAST>CRIT\"\naura_env.suitwwpvestats_druid_guardian_ec = \"ILVL>HASTE>VERS>MAST>CRIT\"\naura_env.suitwwpvestats_druid_restoration_ws = \"ILVL>HASTE>MAST>VERS>CRIT\"\naura_env.suitwwpvestats_druid_restoration_kotg = \"ILVL>HASTE>MAST>VERS>CRIT\"\n\n-- Evoker.  Scalecommander (sc), Flameshaper (fs), Chronowarden (cw)\naura_env.suitwwpvestats_evoker_dev_sc = \"ILVL>CRIT>HASTE>VERS>MAST\"\naura_env.suitwwpvestats_evoker_dev_fs = \"ILVL>HASTE>CRRIT>VERS>MAST\"\naura_env.suitwwpvestats_evoker_pres_fs = \"ILVL>MAST>HASTE(15%)>CRIT>VERS>HASTE(15%+)\"\naura_env.suitwwpvestats_evoker_pres_cw = \"ILVL>MAST>CRIT>VERS>HASTE\"\naura_env.suitwwpvestats_evoker_aug_sc = \"ILVL>CRIT>HASTE>MAST>VERS\"\naura_env.suitwwpvestats_evoker_aug_cw = \"ILVL>MAST>CRIT>HASTE>VERS\"\n\n-- Hunter.  Pack Leader (pl), Dark Ranger (dr), Sentinel (st)\naura_env.suitwwpvestats_hunter_bm_pl = \"WEAP>HASTE>MAST=CRIT>VERS>ILVL\"\naura_env.suitwwpvestats_hunter_bm_dr = \"WEAP>HASTE>CRIT>VERS>MAST>ILVL\"\naura_env.suitwwpvestats_hunter_mm_st = \"ILVL>CRIT>MAST>VERS>HASTE\"\naura_env.suitwwpvestats_hunter_mm_dr = \"ILVL>CRIT>MAST>VERS>HASTE\"\naura_env.suitwwpvestats_hunter_surv_st = \"ILVL>MAST>HASTE>CRIT>VERS\"\naura_env.suitwwpvestats_hunter_surv_pl = \"ILVL>MAST>CRIT>HASTE>VERS\"\n\n-- Mage.  Sunfury (sf), Frostfire (ff), Spellslinger (ss)\naura_env.suitwwpvestats_mage_arcane_sf = \"ILVL>HASTE>VERS>MAST>CRIT\"\naura_env.suitwwpvestats_mage_arcane_ss = \"ILVL>HASTE>VERS>MAST>CRIT\"\naura_env.suitwwpvestats_mage_fire_sf = \"ILVL>HASTE>VERS>MAST>CRIT\"\naura_env.suitwwpvestats_mage_fire_ff = \"ILVL>HASTE>CRIT>VERS>MAST\"\naura_env.suitwwpvestats_mage_frost_ss = \"ILVL>HASTE>MAST>CRIT>VERS\"\naura_env.suitwwpvestats_mage_frost_fr = \"ILVL>HASTE>CRIT>VERS>MAST\"\n\n-- Monk.  Conduit of the Celestials (cotc), Shado-pan (sp), Master of Harmony (moh)\naura_env.suitwwpvestats_monk_ww_cotc = \"ILVL>MAST=HASTE>VERS=CRIT\"\naura_env.suitwwpvestats_monk_ww_sp = \"ILVL>MAST=HASTE>VERS=CRIT\"\naura_env.suitwwpvestats_monk_bm_sp = \"ILVL>VERS=CRIT=MAST>HASTE\"\naura_env.suitwwpvestats_monk_bm_moh = \"ILVL>VERS=CRIT=MAST>HASTE\"\naura_env.suitwwpvestats_monk_mw_cotc = \"ILVL>HASTE>VERS>CRIT>MAST\"\naura_env.suitwwpvestats_monk_mw_moh = \"ILVL>HASTE>CRIT>MAST>VERS\"\n\n-- Paladin.  Templar (tmp), Herald of the Sun (hots), Lightsmith (ls)\naura_env.suitwwpvestats_paladin_ret_tmp = \"ILVL>MAST>CRIT>HASTE>VERS\"\naura_env.suitwwpvestats_paladin_ret_hots = \"ILVL>MAST>CRIT>HASTE