["init"] = {
["do_custom"] = true,
["custom"] = "-- Initialize the central table if it doesn't exist\nQuaziiWA = QuaziiWA or {}\n\nlocal aura_env = aura_env\nlocal config = aura_env.config or {}\n\n-- Store the raw config from Custom Options\nQuaziiWA.rawConfig = config\n\n-- Default configuration values\nlocal defaults = {\n    -- Row 1 Settings\n    firstRowIconCount = 7,\n    firstRowIconWidth = 40,\n    firstRowIconHeight = 30,\n    firstRowStrata = \"MEDIUM\",\n    firstRowIconSpacing = 2,\n    firstRowFont = \"Friz Quadrata TT\",\n    firstRowFontSize = 12,\n    \n    -- Row 2 Settings\n    secondRowIconCount = 8,\n    secondRowIconWidth = 34.6,\n    secondRowIconHeight = 25.95,\n    secondRowStrata = \"LOW\",\n    secondRowIconSpacing = 2,\n    secondRowFont = \"Friz Quadrata TT\",\n    secondRowFontSize = 12,\n    \n    -- Row 3 Settings\n    thirdRowIconCount = 5,\n    thirdRowIconWidth = 34.212,\n    thirdRowIconHeight = 21.14,\n    thirdRowStrata = \"BACKGROUND\",\n    thirdRowIconSpacing = 2,\n    thirdRowFont = \"Friz Quadrata TT\",\n    thirdRowFontSize = 12,\n    \n    -- Vertical spacing between rows\n    verticalSpacing1 = -1.9,\n    verticalSpacing2 = -2.3\n}\n\n-- Function to get the effective configuration (merging defaults and user settings)\nfunction QuaziiWA:GetConfig()\n    local effectiveConfig = {}\n    for k, v in pairs(defaults) do\n        -- Use the value from the user's Custom Options if it exists, otherwise use the default\n        effectiveConfig[k] = QuaziiWA.rawConfig[k] or v\n    end\n    \n    -- Handle select dropdowns correctly (they store the index, we need the value)\n    local strataValues = { \"BACKGROUND\", \"LOW\", \"MEDIUM\", \"HIGH\", \"DIALOG\" }\n    local rawFirstStrata = QuaziiWA.rawConfig.firstRowStrata -- Get potential index from config\n    if type(rawFirstStrata) == \"number\" then\n        effectiveConfig.firstRowStrata = strataValues[rawFirstStrata] or defaults.firstRowStrata -- Use default name if index invalid\n    elseif QuaziiWA.rawConfig.firstRowStrata == nil then -- User hasn't set it\n        effectiveConfig.firstRowStrata = defaults.firstRowStrata -- Use default name\n    else -- User likely provided a string override? Keep it.\n        effectiveConfig.firstRowStrata = QuaziiWA.rawConfig.firstRowStrata\n    end\n    \n    local rawSecondStrata = QuaziiWA.rawConfig.secondRowStrata\n    if type(rawSecondStrata) == \"number\" then\n        effectiveConfig.secondRowStrata = strataValues[rawSecondStrata] or defaults.secondRowStrata\n    elseif QuaziiWA.rawConfig.secondRowStrata == nil then\n        effectiveConfig.secondRowStrata = defaults.secondRowStrata\n    else\n        effectiveConfig.secondRowStrata = QuaziiWA.rawConfig.secondRowStrata\n    end\n    \n    local rawThirdStrata = QuaziiWA.rawConfig.thirdRowStrata\n    if type(rawThirdStrata) == \"number\" then\n        effectiveConfig.thirdRowStrata = strataValues[rawThirdStrata] or defaults.thirdRowStrata\n    elseif QuaziiWA.rawConfig.thirdRowStrata == nil then\n        effectiveConfig.thirdRowStrata = defaults.thirdRowStrata\n    else\n        effectiveConfig.thirdRowStrata = QuaziiWA.rawConfig.thirdRowStrata\n    end\n    \n    return effectiveConfig\nend\n\n-- Define the Grow function for the Abilities group within the central table\nfunction QuaziiWA:GrowAbilities(newPositions, activeRegions)\n    local cfg = self:GetConfig()\n    \n    -- Row Settings from Config\n    local FirstRowLimit = cfg.firstRowIconCount\n    local WidthFirstRow = cfg.firstRowIconWidth\n    local HeightFirstRow = cfg.firstRowIconHeight\n    local StrataFirstRow = cfg.firstRowStrata\n    local SpacingFirstRow = cfg.firstRowIconSpacing\n    local FontFirstRow = cfg.firstRowFont\n    local FontSizeFirstRow = cfg.firstRowFontSize\n    \n    local SecondRowLimit = cfg.secondRowIconCount\n    local WidthSecondRow = cfg.secondRowIconWidth\n    local HeightSecondRow = cfg.secondRowIconHeight\n    local StrataSecondRow = cfg.secondRowStrata\n    local SpacingSecondRow = cfg.secondRowIconSpacing\n    local FontSecondRow = cfg.secondRowFont\n    local FontSizeSecondRow = cfg.secondRowFontSize\n    \n    local ThirdRowLimit = cfg.thirdRowIconCount\n    local WidthThirdRow = cfg.thirdRowIconWidth\n    local HeightThirdRow = cfg.thirdRowIconHeight\n    local StrataThirdRow = cfg.thirdRowStrata\n    local SpacingThirdRow = cfg.thirdRowIconSpacing\n    local FontThirdRow = cfg.thirdRowFont\n    local FontSizeThirdRow = cfg.thirdRowFontSize\n    \n    -- Other Settings from Config\n    local correctionYspacing1 = cfg.verticalSpacing1\n    local correctionYspacing2 = cfg.verticalSpacing2\n    \n    -- Helper function to update text elements in an icon\n    local function updateIconText(region, font, fontSize)\n        -- Check if SharedMedia is available\n        local sharedMedia = LibStub and LibStub(\"LibSharedMedia-3.0\", true)\n        \n        -- Try to get the font object - either directly or via SharedMedia\n        local fontObject = font\n        if sharedMedia then\n            local fetchedFont = sharedMedia:Fetch(\"font\", font)\n            if fetchedFont then\n                fontObject = fetchedFont\n            end\n        end\n        \n        -- Apply to subRegions if they exist\n        if region.subRegions then\n            for _, subRegion in ipairs(region.subRegions) do\n                if subRegion.type == \"subtext\" and subRegion.text and subRegion.text.SetFont then\n                    subRegion.text:SetFont(fontObject, fontSize, \"OUTLINE\")\n                end\n            end\n        end\n        \n        -- Try direct text elements if they exist\n        if region.text and region.text.SetFont then\n            region.text:SetFont(fontObject, fontSize, \"OUTLINE\")\n        end\n        \n        if region.stacks and region.stacks.SetFont then\n            region.stacks:SetFont(fontObject, fontSize, \"OUTLINE\")\n        end\n        \n        if region.timer and region.timer.SetFont then\n            region.timer:SetFont(fontObject, fontSize, \"OUTLINE\")\n        end\n        \n        -- Debug info\n        -- print(\"Applied font:\", font, \"size:\", fontSize, \"to region:\", region:GetName() or \"unnamed\")\n    end\n    \n    -- Original processing logic\n    local function processRow(startIndex, endIndex, width, height, strata, rowSpacing, font, fontSize, yOffset)\n        local xCount = 0\n        local activeInRow = 0\n        for i = startIndex, endIndex do\n            if activeRegions[i] then activeInRow = activeInRow + 1 end\n        end\n        \n        if activeInRow == 0 then return end\n        \n        local startXOffset = 0 - (width + rowSpacing) / 2 * (activeInRow - 1)\n        \n        for i = startIndex, endIndex do\n            if activeRegions[i] then\n                local region = activeRegions[i].region\n                region:Show()\n                region:SetRegionWidth(width)\n                region:SetRegionHeight(height)\n                region:SetFrameStrata(strata)\n                \n                -- Apply fonts to the region\n                updateIconText(region, font, fontSize)\n                \n                local xPos = startXOffset + (xCount * (width + rowSpacing))\n                newPositions[i] = {xPos, yOffset}\n                \n                xCount = xCount + 1\n            end\n        end\n    end\n    \n    local totalIcons = #activeRegions\n    local firstRowEnd = math.min(FirstRowLimit, totalIcons)\n    local secondRowActualStart = firstRowEnd + 1\n    local secondRowEnd = math.min(firstRowEnd + SecondRowLimit, totalIcons)\n    local thirdRowActualStart = secondRowEnd + 1\n    local thirdRowEnd = math.min(secondRowEnd + ThirdRowLimit, totalIcons)\n    \n    -- Process first row with row-specific spacing and font\n    if FirstRowLimit > 0 then\n        processRow(1, firstRowEnd, WidthFirstRow, HeightFirstRow, StrataFirstRow, \n        SpacingFirstRow, FontFirstRow, FontSizeFirstRow, 0)\n    end\n    \n    -- Process second row with row-specific spacing and font\n    if secondRowActualStart <= totalIcons and SecondRowLimit > 0 then\n        processRow(secondRowActualStart, secondRowEnd, WidthSecondRow, HeightSecondRow, StrataSecondRow,\n            SpacingSecondRow, FontSecondRow, FontSizeSecondRow,\n        0 - HeightFirstRow - SpacingFirstRow + correctionYspacing1)\n    end\n    \n    -- Process third row with row-specific spacing and font\n    if thirdRowActualStart <= totalIcons and ThirdRowLimit > 0 then\n        processRow(thirdRowActualStart, thirdRowEnd, WidthThirdRow, HeightThirdRow, StrataThirdRow,\n            SpacingThirdRow, FontThirdRow, FontSizeThirdRow,\n            0 - (HeightFirstRow + HeightSecondRow) - (SpacingFirstRow + SpacingSecondRow) + \n        correctionYspacing1 + correctionYspacing2)\n    end\n    \n    -- Hide any remaining icons\n    for i = thirdRowEnd + 1, totalIcons do\n        if activeRegions[i] then\n            activeRegions[i].region:Hide()\n            newPositions[i] = {0, 0}\n        end\n    end\n    \n    -- Hide icons in rows with 0 limit\n    if FirstRowLimit == 0 then\n        for i = 1, firstRowEnd do\n            if activeRegions[i] then activeRegions[i].region:Hide(); newPositions[i] = {0, 0} end\n        end\n    end\n    if SecondRowLimit == 0 then\n        for i = secondRowActualStart, secondRowEnd do\n            if activeRegions[i] then activeRegions[i].region:Hide(); newPositions[i] = {0, 0} end\n        end\n    end\n    if ThirdRowLimit == 0 then\n        for i = thirdRowActualStart, thirdRowEnd do\n            if activeRegions[i] then activeRegions[i].region:Hide(); newPositions[i] = {0, 0} end\n        end\n    end\nend\n\n-- Function to re-initialize config when options change\nlocal function UpdateConfig()\n    QuaziiWA.rawConfig = aura_env.config or {}\n    print(\"QuaziiWA Config Updated\")\nend\n\n-- WeakAuras automatically calls the init script when options change,\n-- so you don't need to explicitly register for events\n\n\n",
},
},
