["do_glow"] = false,
["custom"] = "\n\n",
["glow_action"] = "show",
["do_custom"] = false,
["glow_frame"] = "WeakAuras:Talents\\Items",
},
["finish"] = {
["custom"] = "aura_env.region:SetScript(\"OnEnter\", nil)\naura_env.region:SetScript(\"OnLeave\", nil)\naura_env.region:EnableMouse(false)",
["do_custom"] = true,
},
["init"] = {
["custom"] = "local aura_env = aura_env\nlocal c = aura_env.config\nlocal region = WeakAuras.GetRegion(aura_env.id)\nlocal _G = _G\nlocal LSM = LibStub(\"LibSharedMedia-3.0\"); \nlocal charsheet = WeakAuras.GetData(\"CCS Character Sheet\")\nlocal inspectsheet = WeakAuras.GetData(\"CCS Inspect Sheet\")\n\naura_env.getraiderioscore = function()\n    local name\n    \n    if InspectFrame and InspectFrame.unit then\n        name = UnitName(InspectFrame.unit)\n    else\n        name = \"\"\n    end\n    \n    local score=0\n    local returnvalue=\"\"\n    local scorecolor=\"\"\n    \n    if aura_env.config.showmythicplusscore ~= true or name == \"\" or name == nil or C_PlayerInfo.GetPlayerMythicPlusRatingSummary(\"target\") == nil or C_PlayerInfo.GetPlayerMythicPlusRatingSummary(\"target\").currentSeasonScore == nil then return \"\" end\n    \n    score = C_PlayerInfo.GetPlayerMythicPlusRatingSummary(\"target\").currentSeasonScore\n    local color = C_ChallengeMode.GetDungeonScoreRarityColor(score)\n    local red = color.r\n    local green = color.g\n    local blue = color.b\n    \n    scorecolor = format(\"|cff%.2x%.2x%.2x\", red*255,green*255,blue*255)\n    \n    returnvalue = format(CHALLENGE_COMPLETE_DUNGEON_SCORE, format(\"%s\", scorecolor) .. score .. format(\"|r\\n\") )\n    \n    \n    return returnvalue\nend\n\naura_env.initframe = function()\n    -- initialize button spacing.\n    if inspectsheet.config.nukeit then return end\n    \n    local spacing = 3\n    local Width = region:GetWidth()\n    local Height = region:GetHeight()\n    local btn = _G[aura_env.id..\"Btn\"] or CreateFrame(\"Frame\", aura_env.id..\"Btn\", region)\n    local textstring = aura_env.getraiderioscore() or \"\"\n    local textoptions = inspectsheet.config.textoutline\n    \n    if textoptions == 1 then textoptions = \"\"\n    elseif textoptions == 2 then textoptions = \"OUTLINE\"\n    elseif textoptions == 3 then textoptions = \"THICKOUTLINE\"\n    end\n    \n    -- Create the main button\n    btn:SetSize(Width, Height)\n    btn:SetPoint(\"TOPLEFT\", InspectFrame, \"TOPLEFT\", 5, -5)\n    btn:SetFrameStrata(\"HIGH\")\n    btn:Show()\n    \n    -- Create the title text\n    local btnfont1 = _G[btn:GetName()..\"fs1\"] or btn:CreateFontString(btn:GetName()..\"fs1\")\n    \n    btnfont1:SetPoint(\"LEFT\", btn, \"LEFT\", 0 ,0)\n    btnfont1:SetFont(LSM:Fetch(\"font\", charsheet.subRegions[2].text_font), c.fontsize_inspect_mplus or 11, textoptions)\n    btnfont1:SetText(textstring)\n    \nend",
["do_custom"] = true,
},
},
