["custom"] = "aura_env.colorString = function(str)\n    return GetClassColoredTextForUnit(\"player\", str)\nend\n\naura_env.latency = 0.0",
["do_custom"] = true,
},
},
["triggers"] = {
{
["trigger"] = {
["subeventSuffix"] = "_CAST_START",
["type"] = "custom",
["subeventPrefix"] = "SPELL",
["unevent"] = "auto",
["names"] = {
},
["use_absorbMode"] = true,
["event"] = "Health",
["use_unit"] = true,
["custom"] = "function()\n    -- Check if it's time to refresh based on the configured interval\n    local c = aura_env.config.QUIData\n    if not aura_env.lastTrigger or aura_env.lastTrigger < GetTime() - c.fpsRefresh then\n        aura_env.lastTrigger = GetTime() -- Update the last trigger time\n        aura_env.fps = GetFramerate() -- Get the current framerate\n    end\n    \n    -- Always return true to allow the display text function to run\n    return true\nend",
["customName"] = "function()\n    -- Throttle the display update to once per second\n    if not aura_env.lastName or aura_env.lastName < GetTime() - 1 then\n        aura_env.lastName = GetTime() -- Update the last name update time\n        \n        -- Format the display string with specific colors\n        if aura_env.fps then -- Ensure FPS has been calculated at least once\n            -- |cff00ff00 starts green color for the number (%.0f)\n            -- |r resets the color after the number\n            -- |cffffffff starts white color for the text \"FPS\" (%s)\n            -- |r resets the color after \"FPS\"\n            aura_env.nameDisplay = (\"|cff00ff00%.0f|r |cffffffff%s|r\"):format(aura_env.fps, \"FPS\")\n        else\n            aura_env.nameDisplay = \"N/A\" -- Show N/A if FPS isn't available yet\n        end\n    end\n    -- Return the formatted string or \"N/A\"\n    return aura_env.nameDisplay or \"N/A\"\nend",
["spellIds"] = {
},
