["init"] = {
["do_custom"] = true,
["custom"] = "-- Initialize the central table if it doesn't exist\nQuaziiWA = QuaziiWA or {}\n\nlocal aura_env = aura_env\nlocal config = aura_env.config or {}\n\n-- Store the raw config from Custom Options\nQuaziiWA.buffConfig = config\n\n-- Default configuration values\nlocal defaults = {\n    buffIconWidth = 30,\n    buffIconHeight = 30,\n    buffFont = \"Friz Quadrata TT\",\n    buffFontSize = 12,\n    buffIconSpacing = 3\n}\n\n-- Function to get the effective configuration (merging defaults and user settings)\nfunction QuaziiWA:GetBuffConfig()\n    local effectiveConfig = {}\n    for k, v in pairs(defaults) do\n        -- Use the value from the user's Custom Options if it exists, otherwise use the default\n        effectiveConfig[k] = QuaziiWA.buffConfig[k] or v\n    end\n    \n    return effectiveConfig\nend\n\n-- Function to update buff icons\nfunction QuaziiWA:UpdateBuffIcons(newPositions, activeRegions)\n    local cfg = self:GetBuffConfig()\n    \n    -- Helper function to update text elements in an icon\n    local function updateIconText(region, font, fontSize)\n        -- Check if SharedMedia is available\n        local sharedMedia = LibStub and LibStub(\"LibSharedMedia-3.0\", true)\n        \n        -- Try to get the font object - either directly or via SharedMedia\n        local fontObject = font\n        if sharedMedia then\n            local fetchedFont = sharedMedia:Fetch(\"font\", font)\n            if fetchedFont then\n                fontObject = fetchedFont\n            end\n        end\n        \n        -- Apply to subRegions if they exist\n        if region.subRegions then\n            for _, subRegion in ipairs(region.subRegions) do\n                if subRegion.type == \"subtext\" and subRegion.text and subRegion.text.SetFont then\n                    subRegion.text:SetFont(fontObject, fontSize, \"OUTLINE\")\n                end\n            end\n        end\n        \n        -- Try direct text elements if they exist\n        if region.text and region.text.SetFont then\n            region.text:SetFont(fontObject, fontSize, \"OUTLINE\")\n        end\n        \n        if region.stacks and region.stacks.SetFont then\n            region.stacks:SetFont(fontObject, fontSize, \"OUTLINE\")\n        end\n        \n        if region.timer and region.timer.SetFont then\n            region.timer:SetFont(fontObject, fontSize, \"OUTLINE\")\n        end\n    end\n    \n    -- Process each region\n    for i, regionData in ipairs(activeRegions) do\n        if regionData and regionData.region then\n            local region = regionData.region\n            \n            -- Set size\n            region:SetRegionWidth(cfg.buffIconWidth)\n            region:SetRegionHeight(cfg.buffIconHeight)\n            \n            -- Update font\n            updateIconText(region, cfg.buffFont, cfg.buffFontSize)\n            \n            -- Original positioning is preserved - newPositions is used by the parent\n        end\n    end\nend\n\n-- Function to re-initialize config when options change\nlocal function UpdateConfig()\n    QuaziiWA.buffConfig = aura_env.config or {}\nend\n\n-- No need for print statements unless debugging\n-- print(\"Buffbar Settings Initialized\")",
},
