},
["custom_type"] = "status",
["custom"] = "function(event, ...)\n    \n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local spellId = select(12, ...)\n        \n        -- pre-filtering by spellId before unpacking and doing more costly checks.\n        if not aura_env.spellList[spellId] then\n            return\n        end\n        \n        local _, subEvent, _, sourceGUID, _, _, _, destGUID = ...\n        \n        if aura_env.playerGUID ~= sourceGUID then\n            return\n        end\n        \n        if destGUID == UnitGUID(\"target\") then\n            aura_env.subEvents_isTarget[subEvent](spellId, subEvent, destGUID, ...)\n        else\n            aura_env.subEvents_noTarget[subEvent](spellId, subEvent, destGUID, ...)\n        end\n        \n    elseif event == \"UNIT_SPELLCAST_SUCCEEDED\" then\n        local spellId = select(3, ...)\n        if spellId == 30455 then -- Ice Lance\n            -- we can't use the SPELL_CAST_SUCCESS combatlog event for this.\n            -- it's filtered by player target and is unreliable during fast target switching.\n            -- for the same reason, we DO need to set the Ice Lance status here.\n            -- this event fires before the combatlog event.\n            aura_env.unbuffedIceLance = not aura_env.PlayerHasFoF()\n        end\n        \n    elseif event == \"TRIGGER\" then\n        -- Winter's Chill from another Trigger\n        -- used to compare real stacks with predicted ones and correct if necessary.\n        -- correcting after a delay because sometimes the real debuff just doesn't update fast enough.\n        -- during a target change we update immediately, since we have no predicted stacks to worry about.\n        local _, info = ...\n        if info[\"\"] then\n            aura_env.wc_stacks_real = info[\"\"].stacks\n            aura_env.wc_expirationTime = info[\"\"].expirationTime\n            aura_env.flurry_flying = false\n            \n            if aura_env.spells_in_flight == 0 -- no airborne spells means prediction will not change\n            and aura_env.flurry_in_flight == 0\n            and aura_env.wc_stacks ~= aura_env.wc_stacks_real then\n                if GetTime() == aura_env.last_target_change then\n                    aura_env.wc_stacks = aura_env.wc_stacks_real\n                    aura_env.is_active = aura_env.wc_stacks > 0\n                else\n                    C_Timer.After(0.2, function() WeakAuras.ScanEvents(\"THV_SWC_Correction\") end)\n                end\n            end\n            aura_env.Send_ScanEvent()\n            \n        else\n            aura_env.wc_stacks_real = 0\n            if aura_env.is_active and aura_env.flurry_in_flight == 0 then\n                aura_env.wc_stacks = 0\n                aura_env.is_active = false\n                aura_env.Send_ScanEvent()\n            end\n        end\n        \n    elseif event == \"UNIT_SPELLCAST_FAILED_QUIET\" then\n        -- used to correct WC after a spell fails to connect or send any combatlog event at all.\n        -- for example when getting hexxed while a spell is already airborne.\n        -- checking if player is currently casting to avoid false positives.\n        local _, _, spellId = ...\n        if UnitExists(\"target\") and aura_env.spellList[spellId] and not UnitCastingInfo(\"player\") then\n            aura_env.spells_in_flight = max(0, aura_env.spells_in_flight - 1)\n            aura_env.Update_WC_debuff()\n            aura_env.Send_ScanEvent()\n        end\n        \n    elseif event == \"PLAYER_TARGET_CHANGED\" then\n        if GetTime() > aura_env.last_target_change then\n            aura_env.last_target_change = GetTime()\n            RunNextFrame(function() WeakAuras.ScanEvents(\"THV_SWC_TargetChanged\") end)\n        end\n        \n    elseif event == \"THV_SWC_TargetChanged\" then\n        if aura_env.last_target ~= UnitGUID(\"target\") then\n            aura_env.last_target = UnitGUID(\"target\")\n            aura_env.Target_Changed()\n            aura_env.Send_ScanEvent()\n        end\n        \n    elseif event == \"LOADING_SCREEN_DISABLED\" then\n        aura_env.Reset_States()\n        aura_env.Send_ScanEvent()\n        \n    elseif event == \"THV_SWC_Correction\" then\n        if aura_env.wc_stacks ~= aura_env.wc_stacks_real then\n            --print(string.format(\" --- Correcting mismatch! --- predicted: '%s' --- actual: '%s'\", aura_env.wc_stacks, aura_env.wc_stacks_real) )\n            aura_env.wc_stacks = aura_env.wc_stacks_real\n            aura_env.is_active = aura_env.wc_stacks > 0\n            aura_env.Send_ScanEvent()\n        end\n        \n    end\n    \n    return\n    \nend",
["events"] = "PLAYER_TARGET_CHANGED,\nLOADING_SCREEN_DISABLED,\nCLEU:SPELL_CAST_SUCCESS:SPELL_DAMAGE:SPELL_ABSORBED:SPELL_MISSED:SPELL_AURA_APPLIED:SPELL_AURA_REMOVED:SPELL_AURA_APPLIED_DOSE:SPELL_AURA_REMOVED_DOSE:SPELL_AURA_REFRESH,\nUNIT_SPELLCAST_FAILED_QUIET:player,\nUNIT_SPELLCAST_SUCCEEDED:player,\nTHV_SWC_Correction,\nTHV_SWC_TargetChanged,\nTRIGGER:3,",
