["custom_type"] = "status",
["check"] = "event",
["unit"] = "player",
["custom"] = "function(event,...)\n    \n    if event == \"THV_SWC_FFB\" then\n        -- happens on first login when spell wasn't loaded yet\n        aura_env.baseDamageFFB = ...\n        \n    elseif event == \"THV_SWC_RequestStatus\" then\n        aura_env.Send_ScanEvent()\n        \n    elseif event == \"PLAYER_TALENT_UPDATE\"\n    or event == \"TRAIT_CONFIG_UPDATED\"\n    or event == \"SPELL_POWER_CHANGED\" then\n        aura_env.UpdateBaseDamageForFFB()\n        \n    elseif event == \"STATUS\" then\n        aura_env.Reset_States()\n        aura_env.wc_stacks_real = 0\n        aura_env.last_target = UnitGUID(\"target\")\n        aura_env.UpdateBaseDamageForFFB()\n        aura_env.Send_ScanEvent()\n        \n    elseif event == \"PLAYER_ENTERING_WORLD\" then\n        local isLogin, _ = ...\n        if isLogin then\n            aura_env.saved.iceNovaBugis_active = false\n        end\n        \n    end\n    \n    return false\nend\n\n\n",
["debuffType"] = "HELPFUL",
