["init"] = {
["custom"] = "-----------------------------------------------\n-- Ice Nova bug - delete this and the Ice Nova combatlog bits when it's fixed!\n-- Ice Nova stops consuming WC after it was automatically triggered by Excess Frost (or Fire in 11.1).\n-----------------------------------------------\naura_env.iceNovaHasBeenCast = false\naura_env.InitIceNovaBug = function()\n    if not aura_env.saved then\n        aura_env.saved = {}\n        aura_env.saved.iceNovaBugIsActive = false\n    end\nend\naura_env.InitIceNovaBug()\n\n-----------------------------------------------\n-- variables and tables\n-----------------------------------------------\naura_env.is_active = false\naura_env.is_immune = false\naura_env.string_immune = \"\"\naura_env.wc_stacks = 0\naura_env.wc_stacks_real = 0\naura_env.fof_stacks = 0\naura_env.spells_in_flight = 0\naura_env.flurry_in_flight = 0\naura_env.flurry_auras = 0 -- used to detect flurry immunities. see SPELL_AURA_APPLIED/REFRESH\naura_env.wc_expirationTime = 0\naura_env.last_FFB_Update = 0 -- keep at 0\naura_env.playerGUID = UnitGUID(\"player\")\naura_env.last_target_change = 0\naura_env.wc_duration = 8\naura_env.flurry_flying = false\n\n-- dont care about PARRY etc\naura_env.missTypeTable = {\n    [\"DEFLECT\"] = true,\n    [\"EVADE\"] = true,\n    [\"IMMUNE\"] = true,\n    [\"MISS\"] = true,\n    [\"REFLECT\"] = true,\n}\n\n-- used to pre-filter incoming combatlog events.\n-- narrows down the events before doing more expensive checks.\naura_env.spellList = {\n    -- dmg\n    [228354] = true, -- Flurry (also applies aura)\n    [228596] = true, -- Flurry\n    [228598] = true, -- Ice Lance\n    [228597] = true, -- Frostbolt\n    [468655] = true, -- Frostfire Bolt\n    [228600] = true, -- Glacial Spike\n    [148022] = true, -- Icicles (only used for immunity detection)\n    -- cast\n    [44614] = true, -- Flurry\n    [30455] = true, -- Ice Lance\n    [116] = true, -- Frostbolt\n    [431044] = true, -- Frostfire Bolt\n    [199786] = true, -- Glacial Spike\n    [157997] = true, -- Ice Nova\n    -- auras\n    --[228358] = true, -- Winter's Chill\n    [44544] = true, -- Fingers of Frost\n}\n\n-----------------------------------------------\n-- misc functions\n-----------------------------------------------\naura_env.Target_Changed = function()\n    aura_env.wc_stacks = aura_env.wc_stacks_real\n    aura_env.is_active = aura_env.wc_stacks > 0\n    aura_env.spells_in_flight = 0\n    aura_env.flurry_in_flight = 0\n    aura_env.flurry_auras = 0\n    aura_env.is_immune = false\n    aura_env.string_immune = \"\"\nend\n\naura_env.Reset_States = function()\n    aura_env.wc_stacks = 0\n    local _, _, fof_stacks =  WA_GetUnitBuff(\"player\", 44544)\n    aura_env.fof_stacks = fof_stacks or 0\n    aura_env.is_active = false\n    aura_env.spells_in_flight = 0\n    aura_env.flurry_in_flight = 0\n    aura_env.flurry_auras = 0\n    aura_env.is_immune = false\n    aura_env.string_immune = \"\"\nend\n\naura_env.Update_WC_debuff = function()\n    aura_env.wc_stacks = aura_env.wc_stacks_real\n    aura_env.is_active = aura_env.wc_stacks > 0\nend\n\naura_env.PlayerHasFoF = function()\n    return aura_env.fof_stacks > 0\nend\n\n-- FFB dots have the same spellID as direct hits.\n-- SPELL_ABSORBED events don't distinguish between direct and periodic damage.\n-- so if a FFB dot is fully absorbed, the WA will mistake it for a FFB hit.\n-- to catch this, we compare absorbed FFB damage against the known base damage of FFB.\naura_env.CheckFFB = function(subEvent, spellId, absorbedDamage)\n    if subEvent == \"SPELL_ABSORBED\"\n    and spellId == 468655\n    and absorbedDamage and absorbedDamage < aura_env.baseDamageFFB then\n        return false\n    else\n        return true\n    end\nend\n\n-- determining base damage for FFB.\n-- this is updated on talent- and spellpower-changes.\naura_env.UpdateBaseDamageForFFB = function()\n    if aura_env.last_FFB_Update > GetTime() then\n        return\n    end\n    \n    aura_env.baseDamageFFB = 20000\n    \n    if not IsPlayerSpell(431044) then\n        return\n    end\n    \n    local description = C_Spell.GetSpellDescription(431044)\n    if description == \"\" then\n        -- spell may not be loaded yet on first login.\n        -- sending baseDamage as ScanEvents cause idk how else to get it out of there!\n        local spell = Spell:CreateFromSpellID(431044)\n        spell:ContinueOnSpellLoad(function()\n                description = spell:GetSpellDescription()\n                local baseDamage = string.match(description, \"%d[%d,]*\")\n                if not baseDamage then return end\n                baseDamage = string.gsub(baseDamage, \",\", \"\")\n                baseDamage = baseDamage * 0.9\n                WeakAuras.ScanEvents(\"THV_WC_FFB\", baseDamage)\n        end)\n        \n    else\n        local baseDamage = string.match(description, \"%d[%d,]*\")\n        if not baseDamage then return end\n        baseDamage = string.gsub(baseDamage, \",\", \"\")\n        baseDamage = baseDamage * 0.9 -- giving some leeway\n        aura_env.baseDamageFFB = baseDamage\n    end\n    \nend\n\n-----------------------------------------------\n-- functions for targeted combatlog events\n-----------------------------------------------\nlocal SPELL_DAMAGE_isTarget = function(spellId, subEvent, destGUID, ...)\n    if spellId == 228354 then -- Flurry\n        aura_env.flurry_in_flight = max(0, aura_env.flurry_in_flight - 1)\n        if aura_env.flurry_in_flight == 0 then\n            aura_env.wc_stacks = 2 - aura_env.spells_in_flight\n        end\n        aura_env.is_active = aura_env.wc_stacks > 0\n        \n    elseif (spellId == 228598 and aura_env.unbuffedIceLance) -- Ice Lance\n    or spellId == 228597 -- Frostbolt\n    or ( spellId == 468655 and aura_env.CheckFFB(subEvent, spellId, select(22, ...)) )-- Frostfire Bolt\n    or spellId == 228600 then -- Glacial Spike\n        if aura_env.flurry_in_flight <= 0 then -- this prevents casts before flurry from borking up the count.\n            if aura_env.spells_in_flight == 0 then\n                aura_env.wc_stacks = max(0, aura_env.wc_stacks - 1)\n            else\n                aura_env.spells_in_flight = max(0, aura_env.spells_in_flight - 1)\n            end\n        end\n        aura_env.is_active = aura_env.wc_stacks > 0\n        \n    elseif spellId == 157997 then -- Ice Nova\n        if aura_env.iceNovaHasBeenCast \n        and not aura_env.saved.iceNovaBugIsActive then\n            -- Ice Nova works normally and consumes WC.\n            if aura_env.flurry_in_flight <= 0 then\n                aura_env.wc_stacks = max(0, aura_env.wc_stacks - 1)\n            end\n            aura_env.is_active = aura_env.wc_stacks > 0\n            \n        elseif not aura_env.iceNovaHasBeenCast then\n            -- Ice Nova trigered automatically, which means the bug is now active.\n            -- Ice Novas will be ignored from now on.\n            aura_env.saved.iceNovaBugIsActive = true\n            \n        end\n        aura_env.iceNovaHasBeenCast = false\n        \n    end\n    aura_env.is_immune = false\n    aura_env.Send_ScanEvent()\nend\n\nlocal SPELL_ABSORBED_isTarget = SPELL_DAMAGE_isTarget\n\nlocal SPELL_CAST_SUCCESS_isTarget = function(spellId, subEvent, destGUID, ...)\n    if spellId == 44614 then -- Flurry\n        aura_env.wc_stacks = 2\n        aura_env.flurry_in_flight = 3\n        aura_env.flurry_auras = 3\n        aura_env.spells_in_flight = 0 -- preceding cast is now a problem\n        aura_env.wc_expirationTime = GetTime() + 8\n        aura_env.is_active = true\n        aura_env.flurry_flying = true\n        \n    elseif spellId == 30455 then -- Ice Lance\n        if aura_env.unbuffedIceLance then\n            aura_env.spells_in_flight = aura_env.spells_in_flight + 1\n            aura_env.wc_stacks = max(0, aura_env.wc_stacks - 1)\n        end\n        aura_env.is_active = aura_env.wc_stacks > 0\n        \n    elseif spellId == 116 -- Frostbolt\n    or spellId == 431044 -- Frostfire Bolt\n    or spellId == 199786 then -- Glacial Spike\n        aura_env.spells_in_flight = aura_env.spells_in_flight + 1\n        aura_env.wc_stacks = max(0, aura_env.wc_stacks - 1)\n        aura_env.is_active = aura_env.wc_stacks > 0\n        \n    elseif spellId == 157997 then -- Ice Nova\n        aura_env.iceNovaHasBeenCast = true\n        C_Timer.After(0.2, function() WeakAuras.ScanEvents(\"THV_WC_Correction\") end)\n        \n    end\n    \n    aura_env.Send_ScanEvent()\n    \nend\n\nlocal SPELL_MISSED_isTarget = function(spellId, subEvent, destGUID, ...)\n    -- see SPELL_AURA_APPLIED_isTarget for some weird case regarding Flurry and immunities.\n    local missType = select(15, ...)\n    if aura_env.missTypeTable[missType] then -- Deflect, Evade, Immune, Miss, Reflect\n        aura_env.wc_stacks = aura_env.wc_stacks_real\n        if spellId == 44614 -- Flurry\n        or spellId == 228596 then -- Flurry\n            aura_env.flurry_in_flight = aura_env.flurry_in_flight - 1\n            \n        elseif (spellId == 228598 and aura_env.unbuffedIceLance) -- Ice Lance\n        or spellId == 228597 -- Frostbolt\n        or spellId == 431044 -- Frostfire Bolt   \n        or spellId == 228600 then -- Glacial Spike\n            aura_env.spells_in_flight = max(0, aura_env.spells_in_flight - 1)\n            \n        end\n        aura_env.is_immune = true\n        aura_env.string_immune = missType\n        aura_env.is_active = aura_env.wc_stacks > 0\n        aura_env.Send_ScanEvent()\n    end\nend\n\nlocal SPELL_AURA_APPLIED_isTarget = function(spellId, subEvent, destGUID, ...)\n    -- when some bosses go immune during transitions, flurry projectiles tend to just dissipate\n    -- without triggering any sort of combatlog event. however, they do apply their debuff for some reason.\n    -- we can use the debuff to check against the flurry projectiles we think are still flying.\n    -- if there's a mismatch, we can assume that the projectiles poofed and that the target is immune.\n    -- the aura triggers before the hit tho (why blizzard??), so we need to check with a delay of one projectile.\n    -- the aura events will be APPLIED, REFRESH, REFRESH.\n    if spellId == 228354 then -- Flurry\n        if aura_env.flurry_auras < aura_env.flurry_in_flight  then\n            -- mismatch means flurry projectiles vanished without doing damage. target must be immune.\n            aura_env.Update_WC_debuff()\n            aura_env.is_immune = true\n            aura_env.string_immune = \"Immune\"\n            aura_env.Send_ScanEvent()\n        end\n        aura_env.flurry_auras = max(0, aura_env.flurry_auras - 1)\n    end\nend\n\nlocal SPELL_AURA_REFRESH_isTarget = SPELL_AURA_APPLIED_isTarget\n\n-----------------------------------------------\n-- functions for other combatlog events\n-----------------------------------------------\nlocal SPELL_AURA_APPLIED_noTarget = function(spellId, subEvent, destGUID, ...)\n    if spellId == 44544 then -- Fingers of Frost\n        aura_env.fof_stacks = 1\n        aura_env.Send_ScanEvent()\n    end\nend\n\nlocal SPELL_AURA_APPLIED_DOSE_noTarget = function(spellId, subEvent, destGUID, ...)\n    if spellId == 44544 then -- Fingers of Frost\n        aura_env.fof_stacks = select(16, ...)\n        aura_env.Send_ScanEvent()\n    end\nend\n\nlocal SPELL_AURA_REMOVED_DOSE_noTarget = SPELL_AURA_APPLIED_DOSE_noTarget\n\nlocal SPELL_AURA_REMOVED_noTarget = function(spellId, subEvent, destGUID, ...)\n    if spellId == 44544 then -- Fingers of Frost\n        aura_env.fof_stacks = 0\n        aura_env.Send_ScanEvent()\n    end\nend\n\n-----------------------------------------------\n-- lookup tables for combatlog events \n-----------------------------------------------\naura_env.subEvents_isTarget = {\n    [\"SPELL_DAMAGE\"] = SPELL_DAMAGE_isTarget,\n    [\"SPELL_ABSORBED\"] = SPELL_ABSORBED_isTarget, -- identical function to previous entry\n    [\"SPELL_CAST_SUCCESS\"] = SPELL_CAST_SUCCESS_isTarget,\n    [\"SPELL_MISSED\"] = SPELL_MISSED_isTarget,\n    [\"SPELL_AURA_APPLIED\"] = SPELL_AURA_APPLIED_isTarget,\n    [\"SPELL_AURA_REFRESH\"] = SPELL_AURA_REFRESH_isTarget, -- identical function to previous entry\n    [\"SPELL_AURA_APPLIED_DOSE\"] = function() end,\n    [\"SPELL_AURA_REMOVED_DOSE\"] = function() end,\n    [\"SPELL_AURA_REMOVED\"] = function() end,\n}\n\naura_env.subEvents_noTarget = {\n    [\"SPELL_DAMAGE\"] = function() end,\n    [\"SPELL_ABSORBED\"] = function() end,\n    [\"SPELL_CAST_SUCCESS\"] = function() end,\n    [\"SPELL_MISSED\"] = function() end,\n    [\"SPELL_AURA_APPLIED\"] = SPELL_AURA_APPLIED_noTarget,\n    [\"SPELL_AURA_REFRESH\"] = function() end,\n    [\"SPELL_AURA_APPLIED_DOSE\"] = SPELL_AURA_APPLIED_DOSE_noTarget,\n    [\"SPELL_AURA_REMOVED_DOSE\"] = SPELL_AURA_REMOVED_DOSE_noTarget, -- identical function to previous entry\n    [\"SPELL_AURA_REMOVED\"] = SPELL_AURA_REMOVED_noTarget,\n}\n\n\n-----------------------------------------------\n-- functions for visual elements (logic-only version)\n--\n-- everything below is the only code that's different between the bar and icon versions\n-----------------------------------------------\n\naura_env.Send_ScanEvent = function()\n    WeakAuras.ScanEvents(\"THV_SWC_Update\", aura_env.is_active, aura_env.wc_stacks, aura_env.wc_expirationTime, aura_env.wc_duration, aura_env.fof_stacks, aura_env.is_immune, aura_env.string_immune, aura_env.flurry_flying)\nend\n\n--[[\nrequired scanevents:\n\nwc stacks change\nfof stacks change\nimmunity change\nwc duration change\nreal_flurry change\nfull reset\ncombat change\n\n\n]]--\n\n\n\n\n\n\n\n\n\n",
["do_custom"] = true,
},
